HZ.gpoints=[{"id":"shi","level":1,"title":"是: A is B","pattern":"A + 是 + B","why":"是 links two nouns: A is B. It never changes, so there is no am, are, is, was or were to choose between.","mark":["是"],"mistake":["我是很高。","我很高。","是 joins nouns. Don't put it in front of a describing word like 高 (see 很)."],"ex":[["我|是|学生|。","wǒ|shì|xué sheng|","I am a student."],["他|是|我|的|老师|。","tā|shì|wǒ|de|lǎo shī|","He is my teacher."],["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."]],"gap":[{"en":"I am Chinese.","before":"我","after":"中国人。","a":"是","wrong":["很","在","吗"],"pins":{"是":"shì","很":"hěn","在":"zài","吗":"ma"},"full":["我|是|中国|人|。","wǒ|shì|Zhōng guó|rén|","I am Chinese."]},{"en":"She is a doctor.","before":"她","after":"医生。","a":"是","wrong":["有","都","了"],"pins":{"是":"shì","有":"yǒu","都":"dōu","了":"le"},"full":["她|是|医生|。","tā|shì|yī shēng|","She is a doctor."]},{"en":"They aren't students.","before":"他们不","after":"学生。","a":"是","wrong":["没","很","在"],"pins":{"是":"shì","没":"méi","很":"hěn","在":"zài"},"full":["他们|不|是|学生|。","tā men|bù|shì|xué sheng|","They aren't students."]}],"order":[{"en":"He is my friend.","a":"他|是|我|的|朋友|。","alt":[],"full":["他|是|我|的|朋友|。","tā|shì|wǒ|de|péng you|","He is my friend."]},{"en":"That is my mum.","a":"那|是|我|妈妈|。","alt":[],"full":["那|是|我|妈妈|。","nà|shì|wǒ|mā ma|","That is my mum."]},{"en":"I am not a teacher.","a":"我|不|是|老师|。","alt":[],"full":["我|不|是|老师|。","wǒ|bù|shì|lǎo shī|","I am not a teacher."]},{"en":"Are you a student?","a":"你|是|学生|吗|？","alt":[],"full":["你|是|学生|吗|？","nǐ|shì|xué sheng|ma|","Are you a student?"]},{"en":"My dad is a doctor.","a":"我|爸爸|是|医生|。","alt":[],"full":["我|爸爸|是|医生|。","wǒ|bà ba|shì|yī shēng|","My dad is a doctor."]}],"spot":[{"en":"I am a student.","right":"我是学生。","wrong":"我学生是。","full":["我|是|学生|。","wǒ|shì|xué sheng|","I am a student."]},{"en":"I am tall.","right":"我很高。","wrong":"我是很高。","full":["我|很|高|。","wǒ|hěn|gāo|","I am tall."]}]},{"id":"bu-mei","level":1,"title":"不 and 没: saying no","pattern":"不 + verb (isn't, won't, doesn't) · 没 + verb (didn't, hasn't)","why":"不 says something isn't so, or that someone doesn't or won't do it. 没 says something didn't happen. 有 always takes 没.","mark":["不","没","没有"],"mistake":["我不有钱。","我没有钱。","有 is the one verb that never takes 不."],"ex":[["我|不|喝|咖啡|。","wǒ|bù|hē|kā fēi|","I don't drink coffee."],["他|昨天|没|来|。","tā|zuó tiān|méi|lái|","He didn't come yesterday."],["我|没有|钱|。","wǒ|méi yǒu|qián|","I don't have any money."]],"gap":[{"en":"I don't have time.","before":"我","after":"有时间。","a":"没","wrong":["不","很","吗"],"pins":{"没":"méi","不":"bù","很":"hěn","吗":"ma"},"full":["我|没有|时间|。","wǒ|méi yǒu|shí jiān|","I don't have time."]},{"en":"She isn't going to school tomorrow.","before":"她明天","after":"去学校。","a":"不","wrong":["没","很","吗"],"pins":{"不":"bù","没":"méi","很":"hěn","吗":"ma"},"full":["她|明天|不|去|学校|。","tā|míng tiān|bù|qù|xué xiào|","She isn't going to school tomorrow."]},{"en":"He didn't come yesterday.","before":"昨天他","after":"来。","a":"没","wrong":["不","也","吗"],"pins":{"没":"méi","不":"bù","也":"yě","吗":"ma"},"full":["昨天|他|没|来|。","zuó tiān|tā|méi|lái|","He didn't come yesterday."]},{"en":"I don't like eating fish.","before":"我","after":"喜欢吃鱼。","a":"不","wrong":["没","是","了"],"pins":{"不":"bù","没":"méi","是":"shì","了":"le"},"full":["我|不|喜欢|吃|鱼|。","wǒ|bù|xǐ huan|chī|yú|","I don't like eating fish."]}],"order":[{"en":"I don't drink tea.","a":"我|不|喝|茶|。","alt":[],"full":["我|不|喝|茶|。","wǒ|bù|hē|chá|","I don't drink tea."]},{"en":"He didn't go yesterday.","a":"他|昨天|没|去|。","alt":["昨天|他|没|去|。"],"full":["他|昨天|没|去|。","tā|zuó tiān|méi|qù|","He didn't go yesterday."]},{"en":"We don't have time today.","a":"今天|我们|没有|时间|。","alt":["我们|今天|没有|时间|。"],"full":["今天|我们|没有|时间|。","jīn tiān|wǒ men|méi yǒu|shí jiān|","We don't have time today."]},{"en":"My mum doesn't eat meat.","a":"我|妈妈|不|吃|肉|。","alt":[],"full":["我|妈妈|不|吃|肉|。","wǒ|mā ma|bù|chī|ròu|","My mum doesn't eat meat."]}],"spot":[{"en":"I don't have any money.","right":"我没有钱。","wrong":"我不有钱。","full":["我|没有|钱|。","wǒ|méi yǒu|qián|","I don't have any money."]},{"en":"He didn't come yesterday.","right":"他昨天没来。","wrong":"他昨天不来。","full":["他|昨天|没|来|。","tā|zuó tiān|méi|lái|","He didn't come yesterday."]}]},{"id":"ma","level":1,"title":"吗: yes-or-no questions","pattern":"Statement + 吗？","why":"Put 吗 on the end of a statement and it becomes a yes-or-no question. The word order stays exactly the same.","mark":["吗"],"mistake":["你叫什么名字吗？","你叫什么名字？","A question word like 什么 already makes a question, so it doesn't need 吗."],"ex":[["你|好|吗|？","nǐ|hǎo|ma|","How are you?"],["你|是|老师|吗|？","nǐ|shì|lǎo shī|ma|","Are you a teacher?"],["他|喝茶|吗|？","tā|hē chá|ma|","Does he drink tea?"]],"gap":[{"en":"Do you like China?","before":"你喜欢中国","after":"？","a":"吗","wrong":["的","了","很"],"pins":{"吗":"ma","的":"de","了":"le","很":"hěn"},"full":["你|喜欢|中国|吗|？","nǐ|xǐ huan|Zhōng guó|ma|","Do you like China?"]},{"en":"Is he a student?","before":"他是学生","after":"？","a":"吗","wrong":["不","是","也"],"pins":{"吗":"ma","不":"bù","是":"shì","也":"yě"},"full":["他|是|学生|吗|？","tā|shì|xué sheng|ma|","Is he a student?"]},{"en":"Is this your book?","before":"这","after":"你的书吗？","a":"是","wrong":["吗","很","了"],"pins":{"是":"shì","吗":"ma","很":"hěn","了":"le"},"full":["这|是|你|的|书|吗|？","zhè|shì|nǐ|de|shū|ma|","Is this your book?"]},{"en":"Are you going to school today?","before":"你今天去学校","after":"？","a":"吗","wrong":["的","很","在"],"pins":{"吗":"ma","的":"de","很":"hěn","在":"zài"},"full":["你|今天|去|学校|吗|？","nǐ|jīn tiān|qù|xué xiào|ma|","Are you going to school today?"]}],"order":[{"en":"Do you drink coffee?","a":"你|喝|咖啡|吗|？","alt":[],"full":["你|喝|咖啡|吗|？","nǐ|hē|kā fēi|ma|","Do you drink coffee?"]},{"en":"Is she your older sister?","a":"她|是|你|的|姐姐|吗|？","alt":[],"full":["她|是|你|的|姐姐|吗|？","tā|shì|nǐ|de|jiě jie|ma|","Is she your older sister?"]},{"en":"Do you have a dog?","a":"你|有|狗|吗|？","alt":[],"full":["你|有|狗|吗|？","nǐ|yǒu|gǒu|ma|","Do you have a dog?"]},{"en":"Is he coming tomorrow?","a":"他|明天|来|吗|？","alt":["明天|他|来|吗|？"],"full":["他|明天|来|吗|？","tā|míng tiān|lái|ma|","Is he coming tomorrow?"]}],"spot":[{"en":"Are you a teacher?","right":"你是老师吗？","wrong":"你吗是老师？","full":["你|是|老师|吗|？","nǐ|shì|lǎo shī|ma|","Are you a teacher?"]},{"en":"What is your name?","right":"你叫什么名字？","wrong":"你叫什么名字吗？","full":["你|叫|什么|名字|？","nǐ|jiào|shén me|míng zi|","What is your name?"]}]},{"id":"de","level":1,"title":"的: my, and describing","pattern":"Owner or description + 的 + noun","why":"The owner or the description always comes before the thing, the opposite of \"the book of mine\". With close family it is often dropped: 我妈妈.","mark":["的"],"mistake":["书的我","我的书","Owner first, then 的, then the thing."],"ex":[["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."],["他|的|朋友|很|好|。","tā|de|péng you|hěn|hǎo|","His friend is very nice."],["我|喜欢|红色|的|车|。","wǒ|xǐ huan|hóng sè|de|chē|","I like red cars."]],"gap":[{"en":"This is the teacher's book.","before":"这是老师","after":"书。","a":"的","wrong":["了","吗","是"],"pins":{"的":"de","了":"le","吗":"ma","是":"shì"},"full":["这|是|老师|的|书|。","zhè|shì|lǎo shī|de|shū|","This is the teacher's book."]},{"en":"That is my computer.","before":"那是我","after":"电脑。","a":"的","wrong":["很","在","不"],"pins":{"的":"de","很":"hěn","在":"zài","不":"bù"},"full":["那|是|我|的|电脑|。","nà|shì|wǒ|de|diàn nǎo|","That is my computer."]},{"en":"She is my friend.","before":"她是我","after":"朋友。","a":"的","wrong":["吗","了","都"],"pins":{"的":"de","吗":"ma","了":"le","都":"dōu"},"full":["她|是|我|的|朋友|。","tā|shì|wǒ|de|péng you|","She is my friend."]},{"en":"Whose book is this?","before":"这是谁","after":"书？","a":"的","wrong":["吗","了","很"],"pins":{"的":"de","吗":"ma","了":"le","很":"hěn"},"full":["这|是|谁|的|书|？","zhè|shì|shéi|de|shū|","Whose book is this?"]}],"order":[{"en":"This is his phone.","a":"这|是|他|的|手机|。","alt":[],"full":["这|是|他|的|手机|。","zhè|shì|tā|de|shǒu jī|","This is his phone."]},{"en":"My friend's home is very big.","a":"我|朋友|的|家|很|大|。","alt":[],"full":["我|朋友|的|家|很|大|。","wǒ|péng you|de|jiā|hěn|dà|","My friend's home is very big."]},{"en":"I like her dog.","a":"我|喜欢|她|的|狗|。","alt":[],"full":["我|喜欢|她|的|狗|。","wǒ|xǐ huan|tā|de|gǒu|","I like her dog."]},{"en":"That is my dad's car.","a":"那|是|我|爸爸|的|车|。","alt":[],"full":["那|是|我|爸爸|的|车|。","nà|shì|wǒ|bà ba|de|chē|","That is my dad's car."]}],"spot":[{"en":"This is my book.","right":"这是我的书。","wrong":"这是书的我。","full":["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."]},{"en":"I like his dog.","right":"我喜欢他的狗。","wrong":"我喜欢狗的他。","full":["我|喜欢|他|的|狗|。","wǒ|xǐ huan|tā|de|gǒu|","I like his dog."]}]},{"id":"measure","level":1,"title":"Measure words","pattern":"Number or 这/那 + measure word + noun","why":"A number can't sit directly on a noun: a measure word goes between them. 个 is the general one, 本 is for books, 杯 for cups and 只 for many animals. For \"two\" of something, say 两, not 二.","mark":["本","杯","个"],"mistake":["我有三书。","我有三本书。","A number needs a measure word before the noun."],"ex":[["我|有|三|本|书|。","wǒ|yǒu|sān|běn|shū|","I have three books."],["我|要|两|杯|茶|。","wǒ|yào|liǎng|bēi|chá|","I'd like two cups of tea."],["这|个|人|是|我|的|老师|。","zhè|gè|rén|shì|wǒ|de|lǎo shī|","This person is my teacher."]],"gap":[{"en":"I have a dog.","before":"我有一","after":"狗。","a":"只","wrong":["本","杯","张"],"pins":{"只":"zhī","本":"běn","杯":"bēi","张":"zhāng"},"full":["我|有|一|只|狗|。","wǒ|yǒu|yī|zhī|gǒu|","I have a dog."]},{"en":"There are three books on the table.","before":"桌子上有三","after":"书。","a":"本","wrong":["只","杯","条"],"pins":{"本":"běn","只":"zhī","杯":"bēi","条":"tiáo"},"full":["桌子|上|有|三|本|书|。","zhuō zi|shang|yǒu|sān|běn|shū|","There are three books on the table."]},{"en":"I'd like a glass of water.","before":"我要一","after":"水。","a":"杯","wrong":["本","只","张"],"pins":{"杯":"bēi","本":"běn","只":"zhī","张":"zhāng"},"full":["我|要|一|杯|水|。","wǒ|yào|yī|bēi|shuǐ|","I'd like a glass of water."]},{"en":"There are five people in our family.","before":"我们家有五","after":"人。","a":"个","wrong":["本","杯","张"],"pins":{"个":"gè","本":"běn","杯":"bēi","张":"zhāng"},"full":["我们|家|有|五|个人|。","wǒ men|jiā|yǒu|wǔ|gè rén|","There are five people in our family."]}],"order":[{"en":"I have two friends.","a":"我|有|两|个|朋友|。","alt":[],"full":["我|有|两|个|朋友|。","wǒ|yǒu|liǎng|gè|péng you|","I have two friends."]},{"en":"This book is very good.","a":"这|本|书|很|好|。","alt":[],"full":["这|本|书|很|好|。","zhè|běn|shū|hěn|hǎo|","This book is very good."]},{"en":"She wants three cups of coffee.","a":"她|要|三|杯|咖啡|。","alt":[],"full":["她|要|三|杯|咖啡|。","tā|yào|sān|bēi|kā fēi|","She wants three cups of coffee."]},{"en":"That person is my dad.","a":"那|个|人|是|我|爸爸|。","alt":[],"full":["那|个|人|是|我|爸爸|。","nà|gè|rén|shì|wǒ|bà ba|","That person is my dad."]}],"spot":[{"en":"I have three books.","right":"我有三本书。","wrong":"我有三书。","full":["我|有|三|本|书|。","wǒ|yǒu|sān|běn|shū|","I have three books."]},{"en":"I have two friends.","right":"我有两个朋友。","wrong":"我有二个朋友。","full":["我|有|两|个|朋友|。","wǒ|yǒu|liǎng|gè|péng you|","I have two friends."]}]},{"id":"hen","level":1,"title":"很 + describing word","pattern":"Noun + 很 + adjective","why":"Chinese adjectives work like verbs, so they don't need 是. 很 usually joins them, and often means little more than \"is\", not a strong \"very\".","mark":["很"],"mistake":["她是漂亮。","她很漂亮。","No 是 before an adjective."],"ex":[["今天|很|热|。","jīn tiān|hěn|rè|","It is hot today."],["这|个|很|好吃|。","zhè|gè|hěn|hǎo chī|","This is delicious."],["她|很|高|。","tā|hěn|gāo|","She is tall."]],"gap":[{"en":"My teacher is nice.","before":"我的老师","after":"好。","a":"很","wrong":["是","的","吗"],"pins":{"很":"hěn","是":"shì","的":"de","吗":"ma"},"full":["我|的|老师|很|好|。","wǒ|de|lǎo shī|hěn|hǎo|","My teacher is nice."]},{"en":"Chinese is hard.","before":"中文","after":"难。","a":"很","wrong":["是","没","的"],"pins":{"很":"hěn","是":"shì","没":"méi","的":"de"},"full":["中文|很|难|。","Zhōng wén|hěn|nán|","Chinese is hard."]},{"en":"The weather is good today.","before":"今天天气","after":"好。","a":"很","wrong":["是","有","在"],"pins":{"很":"hěn","是":"shì","有":"yǒu","在":"zài"},"full":["今天|天气|很|好|。","jīn tiān|tiān qì|hěn|hǎo|","The weather is good today."]},{"en":"This apple is big.","before":"这个苹果","after":"大。","a":"很","wrong":["是","了","吗"],"pins":{"很":"hěn","是":"shì","了":"le","吗":"ma"},"full":["这|个|苹果|很|大|。","zhè|gè|píng guǒ|hěn|dà|","This apple is big."]}],"order":[{"en":"My mum is very busy today.","a":"今天|我|妈妈|很|忙|。","alt":["我|妈妈|今天|很|忙|。"],"full":["今天|我|妈妈|很|忙|。","jīn tiān|wǒ|mā ma|hěn|máng|","My mum is very busy today."]},{"en":"This book is very expensive.","a":"这|本|书|很|贵|。","alt":[],"full":["这|本|书|很|贵|。","zhè|běn|shū|hěn|guì|","This book is very expensive."]},{"en":"The weather is cold today.","a":"今天|天气|很|冷|。","alt":["天气|今天|很|冷|。"],"full":["今天|天气|很|冷|。","jīn tiān|tiān qì|hěn|lěng|","The weather is cold today."]},{"en":"My friend is very tall.","a":"我|朋友|很|高|。","alt":[],"full":["我|朋友|很|高|。","wǒ|péng you|hěn|gāo|","My friend is very tall."]}],"spot":[{"en":"She is beautiful.","right":"她很漂亮。","wrong":"她是漂亮。","full":["她|很|漂亮|。","tā|hěn|piào liang|","She is beautiful."]},{"en":"It is hot today.","right":"今天很热。","wrong":"今天是热。","full":["今天|很|热|。","jīn tiān|hěn|rè|","It is hot today."]}]},{"id":"ye-dou","level":1,"title":"也 and 都: too and all","pattern":"Subject + 也 or 都 + verb","why":"Both go straight before the verb, never at the front of the sentence. 都 sums up the people or things named before it.","mark":["也","都"],"mistake":["也我是学生。","我也是学生。","也 follows the subject and comes before the verb."],"ex":[["我|也|是|学生|。","wǒ|yě|shì|xué sheng|","I am a student too."],["我们|都|喜欢|茶|。","wǒ men|dōu|xǐ huan|chá|","We all like tea."],["他们|都|是|老师|。","tā men|dōu|shì|lǎo shī|","They are all teachers."]],"gap":[{"en":"I drink tea too.","before":"我","after":"喝茶。","a":"也","wrong":["吗","的","很"],"pins":{"也":"yě","吗":"ma","的":"de","很":"hěn"},"full":["我|也|喝茶|。","wǒ|yě|hē chá|","I drink tea too."]},{"en":"They are all Chinese.","before":"他们","after":"是中国人。","a":"都","wrong":["也","很","吗"],"pins":{"都":"dōu","也":"yě","很":"hěn","吗":"ma"},"full":["他们|都|是|中国|人|。","tā men|dōu|shì|Zhōng guó|rén|","They are all Chinese."]},{"en":"She likes cats, and I like cats too.","before":"她喜欢猫，我","after":"喜欢猫。","a":"也","wrong":["都","很","了"],"pins":{"也":"yě","都":"dōu","很":"hěn","了":"le"},"full":["她|喜欢|猫|，|我|也|喜欢|猫|。","tā|xǐ huan|māo||wǒ|yě|xǐ huan|māo|","She likes cats, and I like cats too."]},{"en":"We are all going to school.","before":"我们","after":"去学校。","a":"都","wrong":["也","的","吗"],"pins":{"都":"dōu","也":"yě","的":"de","吗":"ma"},"full":["我们|都|去|学校|。","wǒ men|dōu|qù|xué xiào|","We are all going to school."]}],"order":[{"en":"My friend is also a teacher.","a":"我|朋友|也|是|老师|。","alt":[],"full":["我|朋友|也|是|老师|。","wǒ|péng you|yě|shì|lǎo shī|","My friend is also a teacher."]},{"en":"They all have cars.","a":"他们|都|有|车|。","alt":[],"full":["他们|都|有|车|。","tā men|dōu|yǒu|chē|","They all have cars."]},{"en":"We are all very busy.","a":"我们|都|很|忙|。","alt":[],"full":["我们|都|很|忙|。","wǒ men|dōu|hěn|máng|","We are all very busy."]},{"en":"He also likes dogs.","a":"他|也|喜欢|狗|。","alt":[],"full":["他|也|喜欢|狗|。","tā|yě|xǐ huan|gǒu|","He also likes dogs."]}],"spot":[{"en":"I am a student too.","right":"我也是学生。","wrong":"也我是学生。","full":["我|也|是|学生|。","wǒ|yě|shì|xué sheng|","I am a student too."]},{"en":"We are all going.","right":"我们都去。","wrong":"都我们去。","full":["我们|都|去|。","wǒ men|dōu|qù|","We are all going."]}]},{"id":"zai","level":1,"title":"在 + place + verb","pattern":"Subject + 在 + place + verb","why":"Where something happens comes before the action: literally \"I at home eat\". English puts it at the end.","mark":["在"],"mistake":["我吃饭在家。","我在家吃饭。","The place goes before the verb."],"ex":[["我|在|家|吃饭|。","wǒ|zài|jiā|chī fàn|","I eat at home."],["他|在|学校|工作|。","tā|zài|xué xiào|gōng zuò|","He works at a school."],["她|在|北京|学习|中文|。","tā|zài|Běi jīng|xué xí|Zhōng wén|","She studies Chinese in Beijing."]],"gap":[{"en":"I study at school.","before":"我","after":"学校学习。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["我|在|学校|学习|。","wǒ|zài|xué xiào|xué xí|","I study at school."]},{"en":"They read at home.","before":"他们","after":"家看书。","a":"在","wrong":["很","的","吗"],"pins":{"在":"zài","很":"hěn","的":"de","吗":"ma"},"full":["他们|在|家|看书|。","tā men|zài|jiā|kàn shū|","They read at home."]},{"en":"My mum works at a hospital.","before":"我妈妈","after":"医院工作。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["我|妈妈|在|医院|工作|。","wǒ|mā ma|zài|yī yuàn|gōng zuò|","My mum works at a hospital."]},{"en":"Where do you work?","before":"你","after":"哪儿工作？","a":"在","wrong":["吗","很","了"],"pins":{"在":"zài","吗":"ma","很":"hěn","了":"le"},"full":["你|在|哪儿|工作|？","nǐ|zài|nǎ r|gōng zuò|","Where do you work?"]}],"order":[{"en":"I read at home.","a":"我|在|家|看书|。","alt":[],"full":["我|在|家|看书|。","wǒ|zài|jiā|kàn shū|","I read at home."]},{"en":"She drinks coffee at school.","a":"她|在|学校|喝|咖啡|。","alt":[],"full":["她|在|学校|喝|咖啡|。","tā|zài|xué xiào|hē|kā fēi|","She drinks coffee at school."]},{"en":"We eat at a restaurant.","a":"我们|在|饭店|吃饭|。","alt":[],"full":["我们|在|饭店|吃饭|。","wǒ men|zài|fàn diàn|chī fàn|","We eat at a restaurant."]},{"en":"My dad works in Beijing.","a":"我|爸爸|在|北京|工作|。","alt":[],"full":["我|爸爸|在|北京|工作|。","wǒ|bà ba|zài|Běi jīng|gōng zuò|","My dad works in Beijing."]}],"spot":[{"en":"I eat at home.","right":"我在家吃饭。","wrong":"我吃饭在家。","full":["我|在|家|吃饭|。","wǒ|zài|jiā|chī fàn|","I eat at home."]},{"en":"He works at a school.","right":"他在学校工作。","wrong":"他工作在学校。","full":["他|在|学校|工作|。","tā|zài|xué xiào|gōng zuò|","He works at a school."]}]},{"id":"time","level":1,"title":"Time goes before the verb","pattern":"Time + subject + verb, or subject + time + verb","why":"When something happens goes before the verb, either at the very start of the sentence or just after the subject. It doesn't go at the end, as it can in English.","mark":["明天","今天","晚上","每天","上午","今年"],"mistake":["我去学校明天。","我明天去学校。","The time word comes before the verb."],"ex":[["我|明天|去|北京|。","wǒ|míng tiān|qù|Běi jīng|","I am going to Beijing tomorrow."],["今天|他|不|工作|。","jīn tiān|tā|bù|gōng zuò|","He isn't working today."],["我们|晚上|吃饭|。","wǒ men|wǎn shang|chī fàn|","We eat in the evening."]],"gap":[{"en":"I am going to school tomorrow.","before":"我","after":"去学校。","a":"明天","wrong":["学校","很","吗"],"pins":{"明天":"míng tiān","学校":"xué xiào","很":"hěn","吗":"ma"},"full":["我|明天|去|学校|。","wǒ|míng tiān|qù|xué xiào|","I am going to school tomorrow."]},{"en":"He drinks tea every day.","before":"他","after":"喝茶。","a":"每天","wrong":["很","的","在"],"pins":{"每天":"měi tiān","很":"hěn","的":"de","在":"zài"},"full":["他|每|天|喝茶|。","tā|měi|tiān|hē chá|","He drinks tea every day."]},{"en":"I am not working today.","before":"","after":"我不工作。","a":"今天","wrong":["很","吗","的"],"pins":{"今天":"jīn tiān","很":"hěn","吗":"ma","的":"de"},"full":["今天|我|不|工作|。","jīn tiān|wǒ|bù|gōng zuò|","I am not working today."]},{"en":"We read in the evening.","before":"我们","after":"看书。","a":"晚上","wrong":["是","了","吗"],"pins":{"晚上":"wǎn shang","是":"shì","了":"le","吗":"ma"},"full":["我们|晚上|看书|。","wǒ men|wǎn shang|kàn shū|","We read in the evening."]}],"order":[{"en":"I go to school every day.","a":"我|每天|去|学校|。","alt":["每天|我|去|学校|。"],"full":["我|每天|去|学校|。","wǒ|měi tiān|qù|xué xiào|","I go to school every day."]},{"en":"She is coming tomorrow.","a":"她|明天|来|。","alt":["明天|她|来|。"],"full":["她|明天|来|。","tā|míng tiān|lái|","She is coming tomorrow."]},{"en":"My dad works in the morning.","a":"我|爸爸|上午|工作|。","alt":["上午|我|爸爸|工作|。"],"full":["我|爸爸|上午|工作|。","wǒ|bà ba|shàng wǔ|gōng zuò|","My dad works in the morning."]},{"en":"I am not going to Beijing this year.","a":"今年|我|不|去|北京|。","alt":["我|今年|不|去|北京|。"],"full":["今年|我|不|去|北京|。","jīn nián|wǒ|bù|qù|Běi jīng|","I am not going to Beijing this year."]}],"spot":[{"en":"I am going to school tomorrow.","right":"我明天去学校。","wrong":"我去学校明天。","full":["我|明天|去|学校|。","wǒ|míng tiān|qù|xué xiào|","I am going to school tomorrow."]},{"en":"He drinks tea every day.","right":"他每天喝茶。","wrong":"他喝茶每天。","full":["他|每|天|喝茶|。","tā|měi|tiān|hē chá|","He drinks tea every day."]}]},{"id":"le","level":1,"title":"了 after a verb: it's done","pattern":"Verb + 了 + amount + object","why":"了 after a verb says the action was completed. It isn't a past tense: it marks that something got done, and it usually comes with an amount, as in 三本书. To say it didn't happen, use 没 and drop the 了.","mark":["了"],"mistake":["我没买了书。","我没买书。","没 already says it didn't happen, so 了 goes."],"ex":[["我|买|了|三|本|书|。","wǒ|mǎi|le|sān|běn|shū|","I bought three books."],["他|喝|了|一|杯|茶|。","tā|hē|le|yī|bēi|chá|","He drank a cup of tea."],["她|吃|了|很|多|苹果|。","tā|chī|le|hěn|duō|píng guǒ|","She ate a lot of apples."]],"gap":[{"en":"I bought two cups of coffee.","before":"我买","after":"两杯咖啡。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["我|买|了|两|杯|咖啡|。","wǒ|mǎi|le|liǎng|bēi|kā fēi|","I bought two cups of coffee."]},{"en":"He read three books.","before":"他看","after":"三本书。","a":"了","wrong":["的","很","吗"],"pins":{"了":"le","的":"de","很":"hěn","吗":"ma"},"full":["他|看|了|三|本|书|。","tā|kàn|le|sān|běn|shū|","He read three books."]},{"en":"I didn't buy books yesterday.","before":"昨天我","after":"买书。","a":"没","wrong":["不","了","很"],"pins":{"没":"méi","不":"bù","了":"le","很":"hěn"},"full":["昨天|我|没|买|书|。","zuó tiān|wǒ|méi|mǎi|shū|","I didn't buy books yesterday."]},{"en":"She drank a glass of water.","before":"她喝","after":"一杯水。","a":"了","wrong":["吗","的","也"],"pins":{"了":"le","吗":"ma","的":"de","也":"yě"},"full":["她|喝|了|一|杯|水|。","tā|hē|le|yī|bēi|shuǐ|","She drank a glass of water."]}],"order":[{"en":"I ate two apples.","a":"我|吃|了|两|个|苹果|。","alt":[],"full":["我|吃|了|两|个|苹果|。","wǒ|chī|le|liǎng|gè|píng guǒ|","I ate two apples."]},{"en":"He bought one book.","a":"他|买|了|一|本|书|。","alt":[],"full":["他|买|了|一|本|书|。","tā|mǎi|le|yī|běn|shū|","He bought one book."]},{"en":"We drank three cups of tea.","a":"我们|喝|了|三|杯|茶|。","alt":[],"full":["我们|喝|了|三|杯|茶|。","wǒ men|hē|le|sān|bēi|chá|","We drank three cups of tea."]},{"en":"My friend read this book.","a":"我|朋友|看|了|这|本|书|。","alt":[],"full":["我|朋友|看|了|这|本|书|。","wǒ|péng you|kàn|le|zhè|běn|shū|","My friend read this book."]}],"spot":[{"en":"I didn't buy books.","right":"我没买书。","wrong":"我没买了书。","full":["我|没|买|书|。","wǒ|méi|mǎi|shū|","I didn't buy books."]},{"en":"I bought three books.","right":"我买了三本书。","wrong":"了我买三本书。","full":["我|买|了|三|本|书|。","wǒ|mǎi|le|sān|běn|shū|","I bought three books."]}]},{"id":"you","level":1,"title":"有: have, and there is","pattern":"Person + 有 + thing · Place + 有 + thing","why":"有 means \"have\", and after a place it means \"there is\". Its negative is always 没有.","mark":["有"],"mistake":["教室里是很多人。","教室里有很多人。","For \"there is\", use 有, not 是."],"ex":[["我|有|一|个|哥哥|。","wǒ|yǒu|yī|gè|gē ge|","I have an older brother."],["桌子|上|有|一|本|书|。","zhuō zi|shang|yǒu|yī|běn|shū|","There is a book on the table."],["学校|里|有|很|多|学生|。","xué xiào|li|yǒu|hěn|duō|xué sheng|","There are many students in the school."]],"gap":[{"en":"I have two younger sisters.","before":"我","after":"两个妹妹。","a":"有","wrong":["是","在","很"],"pins":{"有":"yǒu","是":"shì","在":"zài","很":"hěn"},"full":["我|有|两|个|妹妹|。","wǒ|yǒu|liǎng|gè|mèi mei|","I have two younger sisters."]},{"en":"There is a cat at home.","before":"家里","after":"一只猫。","a":"有","wrong":["是","很","吗"],"pins":{"有":"yǒu","是":"shì","很":"hěn","吗":"ma"},"full":["家里|有|一|只|猫|。","jiā li|yǒu|yī|zhī|māo|","There is a cat at home."]},{"en":"He doesn't have a car.","before":"他没","after":"车。","a":"有","wrong":["是","在","很"],"pins":{"有":"yǒu","是":"shì","在":"zài","很":"hěn"},"full":["他|没有|车|。","tā|méi yǒu|chē|","He doesn't have a car."]}],"order":[{"en":"I have many friends.","a":"我|有|很多|朋友|。","alt":[],"full":["我|有|很多|朋友|。","wǒ|yǒu|hěn duō|péng you|","I have many friends."]},{"en":"There are three people at home.","a":"家|里|有|三|个|人|。","alt":[],"full":["家|里|有|三|个|人|。","jiā|li|yǒu|sān|gè|rén|","There are three people at home."]},{"en":"Do you have a phone?","a":"你|有|手机|吗|？","alt":[],"full":["你|有|手机|吗|？","nǐ|yǒu|shǒu jī|ma|","Do you have a phone?"]}],"spot":[{"en":"There are many people in the classroom.","right":"教室里有很多人。","wrong":"教室里是很多人。","full":["教室|里|有|很|多|人|。","jiào shì|li|yǒu|hěn|duō|rén|","There are many people in the classroom."]},{"en":"I don't have an older brother.","right":"我没有哥哥。","wrong":"我不有哥哥。","full":["我|没有|哥哥|。","wǒ|méi yǒu|gē ge|","I don't have an older brother."]}]},{"id":"zai-verb","level":1,"title":"在: is at a place","pattern":"Person or thing + 在 + place","why":"是 says what something is. 在 says where it is, and it is the verb of the sentence, so no 是 is needed.","mark":["在"],"mistake":["他是学校。","他在学校。","He isn't a school: use 在 for where someone is."],"ex":[["我|在|家|。","wǒ|zài|jiā|","I am at home."],["书|在|桌子|上|。","shū|zài|zhuō zi|shang|","The book is on the table."],["你|妈妈|在|哪儿|？","nǐ|mā ma|zài|nǎ r|","Where is your mum?"]],"gap":[{"en":"The teacher is at school.","before":"老师","after":"学校。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["老师|在|学校|。","lǎo shī|zài|xué xiào|","The teacher is at school."]},{"en":"My phone is on the table.","before":"我的手机","after":"桌子上。","a":"在","wrong":["是","的","吗"],"pins":{"在":"zài","是":"shì","的":"de","吗":"ma"},"full":["我|的|手机|在|桌子|上|。","wǒ|de|shǒu jī|zài|zhuō zi|shang|","My phone is on the table."]},{"en":"They are in Beijing.","before":"他们","after":"北京。","a":"在","wrong":["是","很","吗"],"pins":{"在":"zài","是":"shì","很":"hěn","吗":"ma"},"full":["他们|在|北京|。","tā men|zài|Běi jīng|","They are in Beijing."]}],"order":[{"en":"My dad is in Beijing.","a":"我|爸爸|在|北京|。","alt":[],"full":["我|爸爸|在|北京|。","wǒ|bà ba|zài|Běi jīng|","My dad is in Beijing."]},{"en":"Where is your book?","a":"你|的|书|在|哪儿|？","alt":[],"full":["你|的|书|在|哪儿|？","nǐ|de|shū|zài|nǎ r|","Where is your book?"]},{"en":"The cat is on the table.","a":"猫|在|桌子|上|。","alt":[],"full":["猫|在|桌子|上|。","māo|zài|zhuō zi|shang|","The cat is on the table."]}],"spot":[{"en":"He is at the hospital.","right":"他在医院。","wrong":"他是医院。","full":["他|在|医院|。","tā|zài|yī yuàn|","He is at the hospital."]},{"en":"The book is on the table.","right":"书在桌子上。","wrong":"书是桌子上。","full":["书|在|桌子|上|。","shū|zài|zhuō zi|shang|","The book is on the table."]}]},{"id":"ne","level":1,"title":"呢: and you?","pattern":"Topic + 呢？","why":"呢 after a person or thing asks the same question about them, or asks where they are. It saves repeating yourself.","mark":["呢"],"mistake":["我很好，你吗？","我很好，你呢？","吗 needs a whole statement before it. For \"and you?\", use 呢."],"ex":[["我|很|好|，|你|呢|？","wǒ|hěn|hǎo||nǐ|ne|","I'm fine, and you?"],["我|喝茶|，|他|呢|？","wǒ|hē chá||tā|ne|","I'm having tea, what about him?"],["我|的|书|呢|？","wǒ|de|shū|ne|","Where is my book?"]],"gap":[{"en":"I'm a teacher, and you?","before":"我是老师，你","after":"？","a":"呢","wrong":["吗","的","了"],"pins":{"呢":"ne","吗":"ma","的":"de","了":"le"},"full":["我|是|老师|，|你|呢|？","wǒ|shì|lǎo shī||nǐ|ne|","I'm a teacher, and you?"]},{"en":"He is going to Beijing, and you?","before":"他去北京，你","after":"？","a":"呢","wrong":["吗","很","的"],"pins":{"呢":"ne","吗":"ma","很":"hěn","的":"de"},"full":["他|去|北京|，|你|呢|？","tā|qù|Běi jīng||nǐ|ne|","He is going to Beijing, and you?"]},{"en":"Where is my phone?","before":"我的手机","after":"？","a":"呢","wrong":["吗","很","也"],"pins":{"呢":"ne","吗":"ma","很":"hěn","也":"yě"},"full":["我|的|手机|呢|？","wǒ|de|shǒu jī|ne|","Where is my phone?"]}],"order":[{"en":"And your friend?","a":"你|的|朋友|呢|？","alt":[],"full":["你|的|朋友|呢|？","nǐ|de|péng you|ne|","And your friend?"]},{"en":"Where is my dad?","a":"我|爸爸|呢|？","alt":[],"full":["我|爸爸|呢|？","wǒ|bà ba|ne|","Where is my dad?"]},{"en":"Where is the teacher's book?","a":"老师|的|书|呢|？","alt":[],"full":["老师|的|书|呢|？","lǎo shī|de|shū|ne|","Where is the teacher's book?"]}],"spot":[{"en":"I'm busy, and you?","right":"我很忙，你呢？","wrong":"我很忙，你吗？","full":["我|很|忙|，|你|呢|？","wǒ|hěn|máng||nǐ|ne|","I'm busy, and you?"]},{"en":"Where is my book?","right":"我的书呢？","wrong":"我的书吗？","full":["我|的|书|呢|？","wǒ|de|shū|ne|","Where is my book?"]}]},{"id":"qwords","level":1,"title":"Question words stay in place","pattern":"The question word goes where the answer will go","why":"English moves \"what\" and \"where\" to the front. Chinese leaves them where the answer would be, so a question has the same order as its answer.","mark":["什么","谁","哪儿"],"mistake":["什么你喜欢？","你喜欢什么？","Keep the normal word order."],"ex":[["你|喜欢|什么|？","nǐ|xǐ huan|shén me|","What do you like?"],["他|是|谁|？","tā|shì|shéi|","Who is he?"],["你|去|哪儿|？","nǐ|qù|nǎ r|","Where are you going?"]],"gap":[{"en":"What is your name?","before":"你叫","after":"名字？","a":"什么","wrong":["谁","哪儿","吗"],"pins":{"什么":"shén me","谁":"shéi","哪儿":"nǎ r","吗":"ma"},"full":["你|叫|什么|名字|？","nǐ|jiào|shén me|míng zi|","What is your name?"]},{"en":"Who is that person?","before":"那个人是","after":"？","a":"谁","wrong":["什么","哪儿","吗"],"pins":{"谁":"shéi","什么":"shén me","哪儿":"nǎ r","吗":"ma"},"full":["那|个|人|是|谁|？","nà|gè|rén|shì|shéi|","Who is that person?"]},{"en":"Where is your mum?","before":"你妈妈在","after":"？","a":"哪儿","wrong":["什么","谁","很"],"pins":{"哪儿":"nǎ r","什么":"shén me","谁":"shéi","很":"hěn"},"full":["你|妈妈|在|哪儿|？","nǐ|mā ma|zài|nǎ r|","Where is your mum?"]}],"order":[{"en":"What are you eating?","a":"你|吃|什么|？","alt":[],"full":["你|吃|什么|？","nǐ|chī|shén me|","What are you eating?"]},{"en":"Where are you going tomorrow?","a":"你|明天|去|哪儿|？","alt":["明天|你|去|哪儿|？"],"full":["你|明天|去|哪儿|？","nǐ|míng tiān|qù|nǎ r|","Where are you going tomorrow?"]},{"en":"Who is your teacher?","a":"谁|是|你|的|老师|？","alt":["你|的|老师|是|谁|？"],"full":["谁|是|你|的|老师|？","shéi|shì|nǐ|de|lǎo shī|","Who is your teacher?"]}],"spot":[{"en":"What are you drinking?","right":"你喝什么？","wrong":"什么你喝？","full":["你|喝|什么|？","nǐ|hē|shén me|","What are you drinking?"]},{"en":"Where do you live?","right":"你住在哪儿？","wrong":"哪儿你住？","full":["你|住|在|哪儿|？","nǐ|zhù|zài|nǎ r|","Where do you live?"]}]},{"id":"ji-duoshao","level":1,"title":"几 and 多少: how many","pattern":"几 + measure word + noun · 多少 + noun","why":"几 is for numbers you expect to be small, and it needs a measure word. 多少 is for any amount, and often goes straight on the noun, as in 多少钱.","mark":["几","多少"],"mistake":["你有几书？","你有几本书？","几 needs a measure word, just as a number does."],"ex":[["你|有|几|个|孩子|？","nǐ|yǒu|jǐ|gè|hái zi|","How many children do you have?"],["现在|几点|？","xiàn zài|jǐ diǎn|","What time is it now?"],["这|个|多少|钱|？","zhè|gè|duō shao|qián|","How much is this?"]],"gap":[{"en":"How many people are in your family?","before":"你家有","after":"个人？","a":"几","wrong":["什么","谁","很"],"pins":{"几":"jǐ","什么":"shén me","谁":"shéi","很":"hěn"},"full":["你|家|有|几|个|人|？","nǐ|jiā|yǒu|jǐ|gè|rén|","How many people are in your family?"]},{"en":"How much is this book?","before":"这本书","after":"钱？","a":"多少","wrong":["几","什么","很"],"pins":{"多少":"duō shao","几":"jǐ","什么":"shén me","很":"hěn"},"full":["这|本|书|多少|钱|？","zhè|běn|shū|duō shao|qián|","How much is this book?"]},{"en":"What day of the week is it today?","before":"今天星期","after":"？","a":"几","wrong":["什么","多","吗"],"pins":{"几":"jǐ","什么":"shén me","多":"duō","吗":"ma"},"full":["今天|星期几|？","jīn tiān|xīng qī jǐ|","What day of the week is it today?"]}],"order":[{"en":"How many books do you have?","a":"你|有|几|本|书|？","alt":[],"full":["你|有|几|本|书|？","nǐ|yǒu|jǐ|běn|shū|","How many books do you have?"]},{"en":"How much is this cup of tea?","a":"这|杯|茶|多少|钱|？","alt":[],"full":["这|杯|茶|多少|钱|？","zhè|bēi|chá|duō shao|qián|","How much is this cup of tea?"]},{"en":"What time is it now?","a":"现在|几|点|？","alt":[],"full":["现在|几|点|？","xiàn zài|jǐ|diǎn|","What time is it now?"]}],"spot":[{"en":"How many books do you have?","right":"你有几本书？","wrong":"你有几书？","full":["你|有|几|本|书|？","nǐ|yǒu|jǐ|běn|shū|","How many books do you have?"]},{"en":"How much is this?","right":"这个多少钱？","wrong":"这个几钱？","full":["这|个|多少|钱|？","zhè|gè|duō shao|qián|","How much is this?"]}]},{"id":"hui","level":1,"title":"会: can, a skill you learned","pattern":"会 + verb","why":"会 is for what you have learned to do: speak a language, drive, swim. It goes before the verb.","mark":["会"],"mistake":["我会中文说。","我会说中文。","会, then the verb, then what you do."],"ex":[["我|会|说|中文|。","wǒ|huì|shuō|Zhōng wén|","I can speak Chinese."],["他|不|会|开车|。","tā|bù|huì|kāi chē|","He can't drive."],["你|会|做饭|吗|？","nǐ|huì|zuò fàn|ma|","Can you cook?"]],"gap":[{"en":"I can swim.","before":"我","after":"游泳。","a":"会","wrong":["是","很","的"],"pins":{"会":"huì","是":"shì","很":"hěn","的":"de"},"full":["我|会|游泳|。","wǒ|huì|yóu yǒng|","I can swim."]},{"en":"She can't drive.","before":"她不","after":"开车。","a":"会","wrong":["是","很","了"],"pins":{"会":"huì","是":"shì","很":"hěn","了":"le"},"full":["她|不|会|开车|。","tā|bù|huì|kāi chē|","She can't drive."]},{"en":"Can you speak English?","before":"你","after":"说英语吗？","a":"会","wrong":["是","很","了"],"pins":{"会":"huì","是":"shì","很":"hěn","了":"le"},"full":["你|会|说|英语|吗|？","nǐ|huì|shuō|Yīng yǔ|ma|","Can you speak English?"]}],"order":[{"en":"My mum can cook.","a":"我|妈妈|会|做饭|。","alt":[],"full":["我|妈妈|会|做饭|。","wǒ|mā ma|huì|zuò fàn|","My mum can cook."]},{"en":"He can't speak Chinese.","a":"他|不|会|说|中文|。","alt":[],"full":["他|不|会|说|中文|。","tā|bù|huì|shuō|Zhōng wén|","He can't speak Chinese."]},{"en":"Can you drive?","a":"你|会|开车|吗|？","alt":[],"full":["你|会|开车|吗|？","nǐ|huì|kāi chē|ma|","Can you drive?"]}],"spot":[{"en":"I can speak Chinese.","right":"我会说中文。","wrong":"我会中文说。","full":["我|会|说|中文|。","wǒ|huì|shuō|Zhōng wén|","I can speak Chinese."]},{"en":"He can't swim.","right":"他不会游泳。","wrong":"他会不游泳。","full":["他|不|会|游泳|。","tā|bù|huì|yóu yǒng|","He can't swim."]}]},{"id":"xiang","level":1,"title":"想: would like to","pattern":"想 + verb","why":"想 before a verb says what you would like to do. It is softer than 要. 不想 goes in front for \"don't want to\".","mark":["想"],"mistake":["我吃想饭。","我想吃饭。","想 comes before the verb."],"ex":[["我|想|喝|水|。","wǒ|xiǎng|hē|shuǐ|","I'd like some water."],["他|想|去|中国|。","tā|xiǎng|qù|Zhōng guó|","He wants to go to China."],["我|不|想|工作|。","wǒ|bù|xiǎng|gōng zuò|","I don't want to work."]],"gap":[{"en":"I'd like to go to Beijing.","before":"我","after":"去北京。","a":"想","wrong":["是","很","的"],"pins":{"想":"xiǎng","是":"shì","很":"hěn","的":"de"},"full":["我|想|去|北京|。","wǒ|xiǎng|qù|Běi jīng|","I'd like to go to Beijing."]},{"en":"What would you like to eat?","before":"你","after":"吃什么？","a":"想","wrong":["是","很","吗"],"pins":{"想":"xiǎng","是":"shì","很":"hěn","吗":"ma"},"full":["你|想|吃|什么|？","nǐ|xiǎng|chī|shén me|","What would you like to eat?"]},{"en":"She doesn't want to read.","before":"她不","after":"看书。","a":"想","wrong":["是","的","了"],"pins":{"想":"xiǎng","是":"shì","的":"de","了":"le"},"full":["她|不|想|看书|。","tā|bù|xiǎng|kàn shū|","She doesn't want to read."]}],"order":[{"en":"I'd like to buy a book.","a":"我|想|买|一|本|书|。","alt":[],"full":["我|想|买|一|本|书|。","wǒ|xiǎng|mǎi|yī|běn|shū|","I'd like to buy a book."]},{"en":"Would you like some tea?","a":"你|想|喝|茶|吗|？","alt":[],"full":["你|想|喝|茶|吗|？","nǐ|xiǎng|hē|chá|ma|","Would you like some tea?"]},{"en":"We want to go to school tomorrow.","a":"我们|明天|想|去|学校|。","alt":["明天|我们|想|去|学校|。"],"full":["我们|明天|想|去|学校|。","wǒ men|míng tiān|xiǎng|qù|xué xiào|","We want to go to school tomorrow."]}],"spot":[{"en":"I'd like some tea.","right":"我想喝茶。","wrong":"我喝想茶。","full":["我|想|喝茶|。","wǒ|xiǎng|hē chá|","I'd like some tea."]},{"en":"He wants to eat an apple.","right":"他想吃苹果。","wrong":"他吃想苹果。","full":["他|想|吃|苹果|。","tā|xiǎng|chī|píng guǒ|","He wants to eat an apple."]}]},{"id":"neng","level":1,"title":"能: can, if it's possible","pattern":"能 + verb","why":"能 says that something is possible or allowed. 会 is for a skill you have learned; 能 is for whether you are able to right now.","mark":["能"],"mistake":["你能吗帮我？","你能帮我吗？","吗 goes at the very end."],"ex":[["我|明天|能|来|。","wǒ|míng tiān|néng|lái|","I can come tomorrow."],["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"],["这里|不|能|吃饭|。","zhè li|bù|néng|chī fàn|","You can't eat here."]],"gap":[{"en":"I can't come today.","before":"今天我不","after":"来。","a":"能","wrong":["是","很","的"],"pins":{"能":"néng","是":"shì","很":"hěn","的":"de"},"full":["今天|我|不|能|来|。","jīn tiān|wǒ|bù|néng|lái|","I can't come today."]},{"en":"Can you help me?","before":"你","after":"帮我吗？","a":"能","wrong":["是","很","了"],"pins":{"能":"néng","是":"shì","很":"hěn","了":"le"},"full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"You can't drink tea here.","before":"这里不","after":"喝茶。","a":"能","wrong":["是","很","了"],"pins":{"能":"néng","是":"shì","很":"hěn","了":"le"},"full":["这里|不|能|喝茶|。","zhè li|bù|néng|hē chá|","You can't drink tea here."]}],"order":[{"en":"Can you help me?","a":"你|能|帮|我|吗|？","alt":[],"full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"I can't go today.","a":"我|今天|不|能|去|。","alt":["今天|我|不|能|去|。"],"full":["我|今天|不|能|去|。","wǒ|jīn tiān|bù|néng|qù|","I can't go today."]},{"en":"I can come tomorrow.","a":"明天|我|能|来|。","alt":["我|明天|能|来|。"],"full":["明天|我|能|来|。","míng tiān|wǒ|néng|lái|","I can come tomorrow."]}],"spot":[{"en":"Can you help me?","right":"你能帮我吗？","wrong":"你帮能我吗？","full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"You can't eat here.","right":"这里不能吃饭。","wrong":"不能这里吃饭。","full":["这里|不|能|吃饭|。","zhè li|bù|néng|chī fàn|","You can't eat here."]}]},{"id":"he","level":1,"title":"和: and, between nouns","pattern":"Noun + 和 + noun","why":"和 joins people and things. Unlike English \"and\", it doesn't join verbs or whole sentences.","mark":["和"],"mistake":["我吃饭和喝茶。","我吃饭，也喝茶。","和 joins nouns, not actions."],"ex":[["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."],["我|喜欢|猫|和|狗|。","wǒ|xǐ huan|māo|hé|gǒu|","I like cats and dogs."],["爸爸|和|妈妈|都|很|忙|。","bà ba|hé|mā ma|dōu|hěn|máng|","Dad and Mum are both busy."]],"gap":[{"en":"You and I are both students.","before":"我","after":"你都是学生。","a":"和","wrong":["也","很","吗"],"pins":{"和":"hé","也":"yě","很":"hěn","吗":"ma"},"full":["我|和|你|都|是|学生|。","wǒ|hé|nǐ|dōu|shì|xué sheng|","You and I are both students."]},{"en":"I like tea and coffee.","before":"我喜欢茶","after":"咖啡。","a":"和","wrong":["也","是","很"],"pins":{"和":"hé","也":"yě","是":"shì","很":"hěn"},"full":["我|喜欢|茶|和|咖啡|。","wǒ|xǐ huan|chá|hé|kā fēi|","I like tea and coffee."]},{"en":"Dad and Mum are at home.","before":"爸爸","after":"妈妈在家。","a":"和","wrong":["也","很","吗"],"pins":{"和":"hé","也":"yě","很":"hěn","吗":"ma"},"full":["爸爸|和|妈妈|在|家|。","bà ba|hé|mā ma|zài|jiā|","Dad and Mum are at home."]}],"order":[{"en":"He and I are friends.","a":"我|和|他|是|朋友|。","alt":["他|和|我|是|朋友|。"],"full":["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."]},{"en":"She likes cats and dogs.","a":"她|喜欢|猫|和|狗|。","alt":["她|喜欢|狗|和|猫|。"],"full":["她|喜欢|猫|和|狗|。","tā|xǐ huan|māo|hé|gǒu|","She likes cats and dogs."]},{"en":"The teachers and students are all at school.","a":"老师|和|学生|都|在|学校|。","alt":["学生|和|老师|都|在|学校|。"],"full":["老师|和|学生|都|在|学校|。","lǎo shī|hé|xué sheng|dōu|zài|xué xiào|","The teachers and students are all at school."]}],"spot":[{"en":"He and I are friends.","right":"我和他是朋友。","wrong":"我是朋友和他。","full":["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."]},{"en":"I like cats and dogs.","right":"我喜欢猫和狗。","wrong":"我喜欢和猫狗。","full":["我|喜欢|猫|和|狗|。","wǒ|xǐ huan|māo|hé|gǒu|","I like cats and dogs."]}]},{"id":"tai","level":1,"title":"太…了: too, or so","pattern":"太 + adjective + 了","why":"太…了 means \"too\" or, when you are pleased, \"so\". The 了 here has nothing to do with the past. 不太 means \"not very\", and takes no 了.","mark":["太","了"],"mistake":["这个是太贵。","这个太贵了。","No 是, and finish with 了."],"ex":[["太|好|了|！","tài|hǎo|le|","That's great!"],["这|个|太|贵|了|。","zhè|gè|tài|guì|le|","This is too expensive."],["今天|太|热|了|。","jīn tiān|tài|rè|le|","It is so hot today."]],"gap":[{"en":"This book is too expensive.","before":"这本书太贵","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["这|本|书|太|贵|了|。","zhè|běn|shū|tài|guì|le|","This book is too expensive."]},{"en":"That's great!","before":"","after":"好了！","a":"太","wrong":["是","的","吗"],"pins":{"太":"tài","是":"shì","的":"de","吗":"ma"},"full":["太|好|了|！","tài|hǎo|le|","That's great!"]},{"en":"It is too cold today.","before":"今天","after":"冷了。","a":"太","wrong":["是","的","吗"],"pins":{"太":"tài","是":"shì","的":"de","吗":"ma"},"full":["今天|太|冷|了|。","jīn tiān|tài|lěng|le|","It is too cold today."]}],"order":[{"en":"This is too expensive.","a":"这个|太|贵|了|。","alt":[],"full":["这个|太|贵|了|。","zhè gè|tài|guì|le|","This is too expensive."]},{"en":"It is so hot today.","a":"今天|太|热|了|。","alt":[],"full":["今天|太|热|了|。","jīn tiān|tài|rè|le|","It is so hot today."]},{"en":"I am too busy.","a":"我|太|忙|了|。","alt":[],"full":["我|太|忙|了|。","wǒ|tài|máng|le|","I am too busy."]}],"spot":[{"en":"That's great!","right":"太好了！","wrong":"太好吗！","full":["太|好|了|！","tài|hǎo|le|","That's great!"]},{"en":"It is too cold today.","right":"今天太冷了。","wrong":"今天是太冷。","full":["今天|太|冷|了|。","jīn tiān|tài|lěng|le|","It is too cold today."]}]},{"id":"ba-particle","level":1,"title":"吧: let's, and right?","pattern":"Sentence + 吧","why":"吧 softens a sentence into a suggestion (\"let's\"), or turns it into a guess you want confirmed (\"right?\").","mark":["吧"],"mistake":["我们吧走。","我们走吧。","吧 goes at the very end."],"ex":[["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."],["你|是|老师|吧|？","nǐ|shì|lǎo shī|ba|","You're a teacher, right?"],["喝茶|吧|。","hē chá|ba|","Have some tea."]],"gap":[{"en":"Let's eat.","before":"我们吃饭","after":"。","a":"吧","wrong":["吗","很","的"],"pins":{"吧":"ba","吗":"ma","很":"hěn","的":"de"},"full":["我们|吃饭|吧|。","wǒ men|chī fàn|ba|","Let's eat."]},{"en":"You're a student, right?","before":"你是学生","after":"？","a":"吧","wrong":["很","也","是"],"pins":{"吧":"ba","很":"hěn","也":"yě","是":"shì"},"full":["你|是|学生|吧|？","nǐ|shì|xué sheng|ba|","You're a student, right?"]},{"en":"Let's go to Beijing.","before":"我们去北京","after":"。","a":"吧","wrong":["很","也","是"],"pins":{"吧":"ba","很":"hěn","也":"yě","是":"shì"},"full":["我们|去|北京|吧|。","wǒ men|qù|Běi jīng|ba|","Let's go to Beijing."]}],"order":[{"en":"Let's go.","a":"我们|走|吧|。","alt":[],"full":["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."]},{"en":"Let's go together.","a":"我们|一起|去|吧|。","alt":[],"full":["我们|一起|去|吧|。","wǒ men|yī qǐ|qù|ba|","Let's go together."]},{"en":"Have some tea.","a":"你|喝|茶|吧|。","alt":[],"full":["你|喝|茶|吧|。","nǐ|hē|chá|ba|","Have some tea."]}],"spot":[{"en":"Let's go.","right":"我们走吧。","wrong":"我们吧走。","full":["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."]},{"en":"Let's eat together.","right":"我们一起吃饭吧。","wrong":"吧我们一起吃饭。","full":["我们|一起|吃饭|吧|。","wǒ men|yī qǐ|chī fàn|ba|","Let's eat together."]}]},{"id":"yao","level":2,"title":"要: going to, want","pattern":"要 + verb","why":"要 before a verb says you are going to do something, or firmly want to. It is stronger than 想.","mark":["要"],"mistake":["我要去明天。","我明天要去。","The time goes before 要."],"ex":[["我|明天|要|去|北京|。","wǒ|míng tiān|yào|qù|Běi jīng|","I am going to Beijing tomorrow."],["我|要|喝|水|。","wǒ|yào|hē|shuǐ|","I want some water."],["你|要|买|什么|？","nǐ|yào|mǎi|shén me|","What do you want to buy?"]],"gap":[{"en":"I want to buy a book.","before":"我","after":"买一本书。","a":"要","wrong":["是","很","的"],"pins":{"要":"yào","是":"shì","很":"hěn","的":"de"},"full":["我|要|买|一|本|书|。","wǒ|yào|mǎi|yī|běn|shū|","I want to buy a book."]},{"en":"He is going to school tomorrow.","before":"他明天","after":"去学校。","a":"要","wrong":["是","很","的"],"pins":{"要":"yào","是":"shì","很":"hěn","的":"de"},"full":["他|明天|要|去|学校|。","tā|míng tiān|yào|qù|xué xiào|","He is going to school tomorrow."]},{"en":"What do you want to drink?","before":"你","after":"喝什么？","a":"要","wrong":["是","很","吗"],"pins":{"要":"yào","是":"shì","很":"hěn","吗":"ma"},"full":["你|要|喝|什么|？","nǐ|yào|hē|shén me|","What do you want to drink?"]}],"order":[{"en":"I want coffee.","a":"我|要|喝|咖啡|。","alt":[],"full":["我|要|喝|咖啡|。","wǒ|yào|hē|kā fēi|","I want coffee."]},{"en":"What do you want to buy?","a":"你|要|买|什么|？","alt":[],"full":["你|要|买|什么|？","nǐ|yào|mǎi|shén me|","What do you want to buy?"]},{"en":"She is coming tomorrow.","a":"她|明天|要|来|。","alt":["明天|她|要|来|。"],"full":["她|明天|要|来|。","tā|míng tiān|yào|lái|","She is coming tomorrow."]}],"spot":[{"en":"I am going to school tomorrow.","right":"我明天要去学校。","wrong":"我要去学校明天。","full":["我|明天|要|去|学校|。","wǒ|míng tiān|yào|qù|xué xiào|","I am going to school tomorrow."]},{"en":"What do you want to drink?","right":"你要喝什么？","wrong":"你喝要什么？","full":["你|要|喝|什么|？","nǐ|yào|hē|shén me|","What do you want to drink?"]}]},{"id":"zhengzai","level":2,"title":"正在: doing it right now","pattern":"正在 + verb","why":"正在 before a verb says the action is going on right now. 在 alone can do the same, and 呢 often ends the sentence.","mark":["正在"],"mistake":["我正在吃饭了。","我正在吃饭。","正在 means it is still going on, so it doesn't take 了."],"ex":[["我|正在|吃饭|。","wǒ|zhèng zài|chī fàn|","I am eating."],["他|正在|工作|呢|。","tā|zhèng zài|gōng zuò|ne|","He is working."],["妈妈|正在|看书|。","mā ma|zhèng zài|kàn shū|","Mum is reading."]],"gap":[{"en":"I am reading.","before":"我","after":"看书。","a":"正在","wrong":["是","很","了"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","了":"le"},"full":["我|正在|看书|。","wǒ|zhèng zài|kàn shū|","I am reading."]},{"en":"She is working.","before":"她","after":"工作呢。","a":"正在","wrong":["是","很","了"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","了":"le"},"full":["她|正在|工作|呢|。","tā|zhèng zài|gōng zuò|ne|","She is working."]},{"en":"They are eating.","before":"他们","after":"吃饭。","a":"正在","wrong":["是","很","的"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","的":"de"},"full":["他们|正在|吃饭|。","tā men|zhèng zài|chī fàn|","They are eating."]}],"order":[{"en":"Dad is working.","a":"爸爸|正在|工作|。","alt":[],"full":["爸爸|正在|工作|。","bà ba|zhèng zài|gōng zuò|","Dad is working."]},{"en":"We are eating.","a":"我们|正在|吃饭|呢|。","alt":[],"full":["我们|正在|吃饭|呢|。","wǒ men|zhèng zài|chī fàn|ne|","We are eating."]},{"en":"The students are studying Chinese.","a":"学生|正在|学习|中文|。","alt":[],"full":["学生|正在|学习|中文|。","xué sheng|zhèng zài|xué xí|Zhōng wén|","The students are studying Chinese."]}],"spot":[{"en":"I am eating.","right":"我正在吃饭。","wrong":"我正在吃饭了。","full":["我|正在|吃饭|。","wǒ|zhèng zài|chī fàn|","I am eating."]},{"en":"He is working.","right":"他正在工作。","wrong":"他工作正在。","full":["他|正在|工作|。","tā|zhèng zài|gōng zuò|","He is working."]}]},{"id":"guo","level":2,"title":"过: have you ever","pattern":"Verb + 过","why":"过 after a verb says you have done it at some time in your life. To say you never have, use 没, and keep the 过.","mark":["过"],"mistake":["我不去过中国。","我没去过中国。","过 takes 没, not 不."],"ex":[["我|去|过|北京|。","wǒ|qù|guo|Běi jīng|","I have been to Beijing."],["你|吃|过|中国|菜|吗|？","nǐ|chī|guo|Zhōng guó|cài|ma|","Have you ever had Chinese food?"],["我|没|看|过|这|本|书|。","wǒ|méi|kàn|guo|zhè|běn|shū|","I haven't read this book."]],"gap":[{"en":"I have been to China.","before":"我去","after":"中国。","a":"过","wrong":["的","很","吗"],"pins":{"过":"guo","的":"de","很":"hěn","吗":"ma"},"full":["我|去|过|中国|。","wǒ|qù|guo|Zhōng guó|","I have been to China."]},{"en":"She has never eaten fish.","before":"她没吃","after":"鱼。","a":"过","wrong":["的","很","吗"],"pins":{"过":"guo","的":"de","很":"hěn","吗":"ma"},"full":["她|没|吃|过|鱼|。","tā|méi|chī|guo|yú|","She has never eaten fish."]},{"en":"I have never been to Beijing.","before":"我","after":"去过北京。","a":"没","wrong":["不","很","吗"],"pins":{"没":"méi","不":"bù","很":"hěn","吗":"ma"},"full":["我|没|去|过|北京|。","wǒ|méi|qù|guo|Běi jīng|","I have never been to Beijing."]}],"order":[{"en":"I have been to Beijing.","a":"我|去|过|北京|。","alt":[],"full":["我|去|过|北京|。","wǒ|qù|guo|Běi jīng|","I have been to Beijing."]},{"en":"Have you ever had Chinese food?","a":"你|吃|过|中国|菜|吗|？","alt":[],"full":["你|吃|过|中国|菜|吗|？","nǐ|chī|guo|Zhōng guó|cài|ma|","Have you ever had Chinese food?"]},{"en":"I haven't read this book.","a":"我|没|看|过|这|本|书|。","alt":[],"full":["我|没|看|过|这|本|书|。","wǒ|méi|kàn|guo|zhè|běn|shū|","I haven't read this book."]}],"spot":[{"en":"I have never been to China.","right":"我没去过中国。","wrong":"我不去过中国。","full":["我|没|去|过|中国|。","wǒ|méi|qù|guo|Zhōng guó|","I have never been to China."]},{"en":"Have you been to Beijing?","right":"你去过北京吗？","wrong":"你过去北京吗？","full":["你|去|过|北京|吗|？","nǐ|qù|guo|Běi jīng|ma|","Have you been to Beijing?"]}]},{"id":"bi","level":2,"title":"比: more than","pattern":"A + 比 + B + adjective","why":"比 compares two things, and the adjective alone already means \"more\". That is why 很 can't go with it.","mark":["比"],"mistake":["他比我很高。","他比我高。","No 很 in a 比 sentence."],"ex":[["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."],["今天|比|昨天|热|。","jīn tiān|bǐ|zuó tiān|rè|","Today is hotter than yesterday."],["这|本|书|比|那|本|书|贵|。","zhè|běn|shū|bǐ|nà|běn|shū|guì|","This book is more expensive than that one."]],"gap":[{"en":"I am taller than him.","before":"我","after":"他高。","a":"比","wrong":["很","是","的"],"pins":{"比":"bǐ","很":"hěn","是":"shì","的":"de"},"full":["我|比|他|高|。","wǒ|bǐ|tā|gāo|","I am taller than him."]},{"en":"Today is colder than yesterday.","before":"今天","after":"昨天冷。","a":"比","wrong":["很","是","的"],"pins":{"比":"bǐ","很":"hěn","是":"shì","的":"de"},"full":["今天|比|昨天|冷|。","jīn tiān|bǐ|zuó tiān|lěng|","Today is colder than yesterday."]},{"en":"This one is bigger than that one.","before":"这个比那个","after":"。","a":"大","wrong":["很","是","吗"],"pins":{"大":"dà","很":"hěn","是":"shì","吗":"ma"},"full":["这|个|比|那|个|大|。","zhè|gè|bǐ|nà|gè|dà|","This one is bigger than that one."]}],"order":[{"en":"He is taller than me.","a":"他|比|我|高|。","alt":[],"full":["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."]},{"en":"Today is hotter than yesterday.","a":"今天|比|昨天|热|。","alt":[],"full":["今天|比|昨天|热|。","jīn tiān|bǐ|zuó tiān|rè|","Today is hotter than yesterday."]},{"en":"This book is more expensive than that book.","a":"这|本|书|比|那|本|书|贵|。","alt":[],"full":["这|本|书|比|那|本|书|贵|。","zhè|běn|shū|bǐ|nà|běn|shū|guì|","This book is more expensive than that book."]}],"spot":[{"en":"He is taller than me.","right":"他比我高。","wrong":"他比我很高。","full":["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."]},{"en":"Today is colder than yesterday.","right":"今天比昨天冷。","wrong":"今天冷比昨天。","full":["今天|比|昨天|冷|。","jīn tiān|bǐ|zuó tiān|lěng|","Today is colder than yesterday."]}]},{"id":"yiyang","level":2,"title":"跟…一样: the same as","pattern":"A + 跟 + B + 一样 + (adjective)","why":"跟…一样 says two things are the same. Add an adjective to say in what way: as tall as, as cold as.","mark":["一样","跟"],"mistake":["我跟他一样很高。","我跟他一样高。","No 很 before the adjective here."],"ex":[["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."],["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."],["今天|跟|昨天|一样|冷|。","jīn tiān|gēn|zuó tiān|yī yàng|lěng|","Today is as cold as yesterday."]],"gap":[{"en":"I am as tall as him.","before":"我","after":"他一样高。","a":"跟","wrong":["比","很","是"],"pins":{"跟":"gēn","比":"bǐ","很":"hěn","是":"shì"},"full":["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."]},{"en":"This is the same as that.","before":"这个跟那个","after":"。","a":"一样","wrong":["很","比","吗"],"pins":{"一样":"yī yàng","很":"hěn","比":"bǐ","吗":"ma"},"full":["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."]},{"en":"Today is as hot as yesterday.","before":"今天跟昨天一样","after":"。","a":"热","wrong":["很","比","吗"],"pins":{"热":"rè","很":"hěn","比":"bǐ","吗":"ma"},"full":["今天|跟|昨天|一样|热|。","jīn tiān|gēn|zuó tiān|yī yàng|rè|","Today is as hot as yesterday."]}],"order":[{"en":"I am as tall as her.","a":"我|跟|她|一样|高|。","alt":[],"full":["我|跟|她|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as her."]},{"en":"This book is the same as that book.","a":"这|本|书|跟|那|本|书|一样|。","alt":[],"full":["这|本|书|跟|那|本|书|一样|。","zhè|běn|shū|gēn|nà|běn|shū|yī yàng|","This book is the same as that book."]},{"en":"Today is as cold as yesterday.","a":"今天|跟|昨天|一样|冷|。","alt":[],"full":["今天|跟|昨天|一样|冷|。","jīn tiān|gēn|zuó tiān|yī yàng|lěng|","Today is as cold as yesterday."]}],"spot":[{"en":"I am as tall as him.","right":"我跟他一样高。","wrong":"我跟他一样很高。","full":["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."]},{"en":"This is the same as that.","right":"这个跟那个一样。","wrong":"这个一样跟那个。","full":["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."]}]},{"id":"de-how","level":2,"title":"得: how something is done","pattern":"Verb + 得 + how","why":"得 after a verb describes how well or how fast it is done. If there is an object, it goes first: 他中文说得很好.","mark":["得"],"mistake":["他说得中文很好。","他中文说得很好。","The object can't come straight after 得."],"ex":[["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."],["她|说|得|很|好|。","tā|shuō|de|hěn|hǎo|","She speaks well."],["我|吃|得|很|多|。","wǒ|chī|de|hěn|duō|","I eat a lot."]],"gap":[{"en":"He runs fast.","before":"他跑","after":"很快。","a":"得","wrong":["的","了","吗"],"pins":{"得":"de","的":"de","了":"le","吗":"ma"},"full":["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."]},{"en":"She writes well.","before":"她写","after":"很好。","a":"得","wrong":["的","了","吗"],"pins":{"得":"de","的":"de","了":"le","吗":"ma"},"full":["她|写|得|很|好|。","tā|xiě|de|hěn|hǎo|","She writes well."]},{"en":"You speak too fast.","before":"你说","after":"太快了。","a":"得","wrong":["的","吗","也"],"pins":{"得":"de","的":"de","吗":"ma","也":"yě"},"full":["你|说|得|太|快|了|。","nǐ|shuō|de|tài|kuài|le|","You speak too fast."]}],"order":[{"en":"He runs fast.","a":"他|跑|得|很|快|。","alt":[],"full":["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."]},{"en":"She does it very well.","a":"她|做|得|很|好|。","alt":[],"full":["她|做|得|很|好|。","tā|zuò|de|hěn|hǎo|","She does it very well."]},{"en":"I ate a lot today.","a":"我|今天|吃|得|很|多|。","alt":["今天|我|吃|得|很|多|。"],"full":["我|今天|吃|得|很|多|。","wǒ|jīn tiān|chī|de|hěn|duō|","I ate a lot today."]}],"spot":[{"en":"He speaks very well.","right":"他说得很好。","wrong":"他说很好得。","full":["他|说|得|很|好|。","tā|shuō|de|hěn|hǎo|","He speaks very well."]},{"en":"He speaks Chinese very well.","right":"他中文说得很好。","wrong":"他说得中文很好。","full":["他|中文|说|得|很|好|。","tā|Zhōng wén|shuō|de|hěn|hǎo|","He speaks Chinese very well."]}]},{"id":"gei","level":2,"title":"给: for, or to someone","pattern":"给 + person + verb","why":"给 before a person says who the action is for or to. As a verb on its own, it simply means \"give\".","mark":["给"],"mistake":["我给打电话他。","我给他打电话。","The person goes straight after 给."],"ex":[["我|给|他|打电话|。","wǒ|gěi|tā|dǎ diàn huà|","I'll phone him."],["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."],["老师|给|我们|一|本|书|。","lǎo shī|gěi|wǒ men|yī|běn|shū|","The teacher gives us a book."]],"gap":[{"en":"I'm phoning my mum.","before":"我","after":"妈妈打电话。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["我|给|妈妈|打电话|。","wǒ|gěi|mā ma|dǎ diàn huà|","I'm phoning my mum."]},{"en":"He bought me a cup of tea.","before":"他","after":"我买了一杯茶。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["他|给|我|买|了|一|杯|茶|。","tā|gěi|wǒ|mǎi|le|yī|bēi|chá|","He bought me a cup of tea."]},{"en":"Please give me a glass of water.","before":"请","after":"我一杯水。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["请|给|我|一|杯|水|。","qǐng|gěi|wǒ|yī|bēi|shuǐ|","Please give me a glass of water."]}],"order":[{"en":"I'll phone him.","a":"我|给|他|打|电话|。","alt":[],"full":["我|给|他|打|电话|。","wǒ|gěi|tā|dǎ|diàn huà|","I'll phone him."]},{"en":"Mum cooks for me.","a":"妈妈|给|我|做饭|。","alt":[],"full":["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."]},{"en":"Please give me a cup of tea.","a":"请|给|我|一|杯|茶|。","alt":[],"full":["请|给|我|一|杯|茶|。","qǐng|gěi|wǒ|yī|bēi|chá|","Please give me a cup of tea."]}],"spot":[{"en":"I'll phone him.","right":"我给他打电话。","wrong":"我给打电话他。","full":["我|给|他|打电话|。","wǒ|gěi|tā|dǎ diàn huà|","I'll phone him."]},{"en":"Mum cooks for me.","right":"妈妈给我做饭。","wrong":"妈妈做饭我给。","full":["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."]}]},{"id":"cong-dao","level":2,"title":"从…到: from and to","pattern":"从 + start + 到 + end","why":"从 marks where or when something starts, 到 where or when it ends. The whole phrase goes before the verb.","mark":["从","到"],"mistake":["我来从北京。","我从北京来。","从 and its place come before the verb."],"ex":[["从|我|家|到|学校|很|近|。","cóng|wǒ|jiā|dào|xué xiào|hěn|jìn|","It is close from my home to the school."],["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."],["我|从|八|点|到|五|点|工作|。","wǒ|cóng|bā|diǎn|dào|wǔ|diǎn|gōng zuò|","I work from eight to five."]],"gap":[{"en":"I come from Beijing.","before":"我","after":"北京来。","a":"从","wrong":["到","很","的"],"pins":{"从":"cóng","到":"dào","很":"hěn","的":"de"},"full":["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."]},{"en":"From eight to five.","before":"从八点","after":"五点。","a":"到","wrong":["从","很","的"],"pins":{"到":"dào","从":"cóng","很":"hěn","的":"de"},"full":["从|八|点|到|五|点|。","cóng|bā|diǎn|dào|wǔ|diǎn|","From eight to five."]},{"en":"They go from Shanghai to Beijing.","before":"他们","after":"上海到北京。","a":"从","wrong":["比","很","的"],"pins":{"从":"cóng","比":"bǐ","很":"hěn","的":"de"},"full":["他们|从|上海|到|北京|。","tā men|cóng|Shàng hǎi|dào|Běi jīng|","They go from Shanghai to Beijing."]}],"order":[{"en":"I come from China.","a":"我|从|中国|来|。","alt":[],"full":["我|从|中国|来|。","wǒ|cóng|Zhōng guó|lái|","I come from China."]},{"en":"It is close from my home to the school.","a":"从|我|家|到|学校|很|近|。","alt":[],"full":["从|我|家|到|学校|很|近|。","cóng|wǒ|jiā|dào|xué xiào|hěn|jìn|","It is close from my home to the school."]},{"en":"I work from eight to five.","a":"我|从|八|点|到|五|点|工作|。","alt":[],"full":["我|从|八|点|到|五|点|工作|。","wǒ|cóng|bā|diǎn|dào|wǔ|diǎn|gōng zuò|","I work from eight to five."]}],"spot":[{"en":"I come from Beijing.","right":"我从北京来。","wrong":"我来从北京。","full":["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."]},{"en":"It is far from here to there.","right":"从这儿到那儿很远。","wrong":"到这儿从那儿很远。","full":["从|这儿|到|那儿|很|远|。","cóng|zhèr|dào|nà r|hěn|yuǎn|","It is far from here to there."]}]},{"id":"li","level":2,"title":"离: how far from","pattern":"A + 离 + B + 远 or 近","why":"离 says how far apart two places are, or two times. English says \"from\" here, but 从 won't do: 从 is for moving, 离 for distance.","mark":["离"],"mistake":["我家从学校很近。","我家离学校很近。","For distance, use 离."],"ex":[["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."],["北京|离|上海|很|远|。","Běi jīng|lí|Shàng hǎi|hěn|yuǎn|","Beijing is far from Shanghai."],["这儿|离|医院|不|远|。","zhèr|lí|yī yuàn|bù|yuǎn|","It isn't far from here to the hospital."]],"gap":[{"en":"My home is close to the school.","before":"我家","after":"学校很近。","a":"离","wrong":["从","比","和"],"pins":{"离":"lí","从":"cóng","比":"bǐ","和":"hé"},"full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"It is far from here to Beijing.","before":"这儿","after":"北京很远。","a":"离","wrong":["从","在","是"],"pins":{"离":"lí","从":"cóng","在":"zài","是":"shì"},"full":["这儿|离|北京|很|远|。","zhèr|lí|Běi jīng|hěn|yuǎn|","It is far from here to Beijing."]},{"en":"The school isn't far from my home.","before":"学校离我家不","after":"。","a":"远","wrong":["离","很","吗"],"pins":{"远":"yuǎn","离":"lí","很":"hěn","吗":"ma"},"full":["学校|离|我|家|不|远|。","xué xiào|lí|wǒ|jiā|bù|yuǎn|","The school isn't far from my home."]}],"order":[{"en":"My home is close to the school.","a":"我|家|离|学校|很|近|。","alt":[],"full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"Beijing is far from Shanghai.","a":"北京|离|上海|很|远|。","alt":["上海|离|北京|很|远|。"],"full":["北京|离|上海|很|远|。","Běi jīng|lí|Shàng hǎi|hěn|yuǎn|","Beijing is far from Shanghai."]},{"en":"The hospital isn't far from here.","a":"医院|离|这儿|不|远|。","alt":[],"full":["医院|离|这儿|不|远|。","yī yuàn|lí|zhèr|bù|yuǎn|","The hospital isn't far from here."]}],"spot":[{"en":"My home is close to the school.","right":"我家离学校很近。","wrong":"我家从学校很近。","full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"It is far from here to Beijing.","right":"这儿离北京很远。","wrong":"这儿很远离北京。","full":["这儿|离|北京|很|远|。","zhèr|lí|Běi jīng|hěn|yuǎn|","It is far from here to Beijing."]}]},{"id":"yinwei","level":2,"title":"因为…所以: because, so","pattern":"因为 + reason，所以 + result","why":"Chinese often marks both halves: the reason with 因为, the result with 所以. In English you would use only one of them.","mark":["因为","所以"],"mistake":["所以下雨，因为我不去。","因为下雨，所以我不去。","The reason comes first, with 因为."],"ex":[["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."],["因为|他|很|忙|，|所以|没|来|。","yīn wèi|tā|hěn|máng||suǒ yǐ|méi|lái|","He is busy, so he didn't come."],["因为|我|喜欢|中国|，|所以|学|中文|。","yīn wèi|wǒ|xǐ huan|Zhōng guó||suǒ yǐ|xué|Zhōng wén|","I like China, so I study Chinese."]],"gap":[{"en":"Because it's cold today, I'm not going.","before":"","after":"今天很冷，所以我不去。","a":"因为","wrong":["但是","虽然","如果"],"pins":{"因为":"yīn wèi","但是":"dàn shì","虽然":"suī rán","如果":"rú guǒ"},"full":["因为|今天|很|冷|，|所以|我|不|去|。","yīn wèi|jīn tiān|hěn|lěng||suǒ yǐ|wǒ|bù|qù|","Because it's cold today, I'm not going."]},{"en":"He is ill, so he didn't come to school.","before":"因为他病了，","after":"没来学校。","a":"所以","wrong":["但是","虽然","因为"],"pins":{"所以":"suǒ yǐ","但是":"dàn shì","虽然":"suī rán","因为":"yīn wèi"},"full":["因为|他|病|了|，|所以|没|来|学校|。","yīn wèi|tā|bìng|le||suǒ yǐ|méi|lái|xué xiào|","He is ill, so he didn't come to school."]},{"en":"It's too expensive, so I'm not buying it.","before":"因为太贵了，","after":"我不买。","a":"所以","wrong":["但是","如果","也"],"pins":{"所以":"suǒ yǐ","但是":"dàn shì","如果":"rú guǒ","也":"yě"},"full":["因为|太|贵|了|，|所以|我|不|买|。","yīn wèi|tài|guì|le||suǒ yǐ|wǒ|bù|mǎi|","It's too expensive, so I'm not buying it."]}],"order":[{"en":"Because it's raining, I'm not going.","a":"因为|下雨|，|所以|我|不|去|。","alt":[],"full":["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."]},{"en":"He is too busy, so he didn't come.","a":"因为|太|忙|，|所以|他|没|来|。","alt":[],"full":["因为|太|忙|，|所以|他|没|来|。","yīn wèi|tài|máng||suǒ yǐ|tā|méi|lái|","He is too busy, so he didn't come."]},{"en":"Because it's cold, I'm not going.","a":"因为|很|冷|，|所以|我|不|去|。","alt":[],"full":["因为|很|冷|，|所以|我|不|去|。","yīn wèi|hěn|lěng||suǒ yǐ|wǒ|bù|qù|","Because it's cold, I'm not going."]}],"spot":[{"en":"Because it's raining, I'm not going.","right":"因为下雨，所以我不去。","wrong":"所以下雨，因为我不去。","full":["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."]},{"en":"I was busy, so I didn't come.","right":"因为很忙，所以我没来。","wrong":"因为很忙，但是我没来。","full":["因为|很|忙|，|所以|我|没|来|。","yīn wèi|hěn|máng||suǒ yǐ|wǒ|méi|lái|","I was busy, so I didn't come."]}]},{"id":"suiran","level":2,"title":"虽然…但是: although, but","pattern":"虽然 + one thing，但是 + the other","why":"Saying \"although … but\" is wrong in English, and right in Chinese. Both halves are normally marked.","mark":["虽然","但是"],"mistake":["虽然很贵，所以我买了。","虽然很贵，但是我买了。","虽然 pairs with 但是, not 所以."],"ex":[["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."],["虽然|下雨|，|但是|他|来|了|。","suī rán|xià yǔ||dàn shì|tā|lái|le|","Although it was raining, he came."],["虽然|很|累|，|但是|我|很|高兴|。","suī rán|hěn|lèi||dàn shì|wǒ|hěn|gāo xìng|","I'm tired, but I'm happy."]],"gap":[{"en":"It's expensive, but I want to buy it.","before":"","after":"很贵，但是我想买。","a":"虽然","wrong":["因为","如果","所以"],"pins":{"虽然":"suī rán","因为":"yīn wèi","如果":"rú guǒ","所以":"suǒ yǐ"},"full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]},{"en":"It's cold, but I'm going.","before":"虽然很冷，","after":"我要去。","a":"但是","wrong":["所以","因为","如果"],"pins":{"但是":"dàn shì","所以":"suǒ yǐ","因为":"yīn wèi","如果":"rú guǒ"},"full":["虽然|很|冷|，|但是|我|要|去|。","suī rán|hěn|lěng||dàn shì|wǒ|yào|qù|","It's cold, but I'm going."]},{"en":"He is busy, but he came.","before":"虽然他很忙，","after":"他来了。","a":"但是","wrong":["所以","因为","也"],"pins":{"但是":"dàn shì","所以":"suǒ yǐ","因为":"yīn wèi","也":"yě"},"full":["虽然|他|很|忙|，|但是|他|来|了|。","suī rán|tā|hěn|máng||dàn shì|tā|lái|le|","He is busy, but he came."]}],"order":[{"en":"I'm tired, but I'm happy.","a":"虽然|很|累|，|但是|我|很|高兴|。","alt":[],"full":["虽然|很|累|，|但是|我|很|高兴|。","suī rán|hěn|lèi||dàn shì|wǒ|hěn|gāo xìng|","I'm tired, but I'm happy."]},{"en":"Although it was raining, he came.","a":"虽然|下雨|，|但是|他|来|了|。","alt":[],"full":["虽然|下雨|，|但是|他|来|了|。","suī rán|xià yǔ||dàn shì|tā|lái|le|","Although it was raining, he came."]},{"en":"It's expensive, but I want to buy it.","a":"虽然|很|贵|，|但是|我|想|买|。","alt":[],"full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]}],"spot":[{"en":"It's expensive, but I want to buy it.","right":"虽然很贵，但是我想买。","wrong":"虽然很贵，所以我想买。","full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]},{"en":"Although it's raining, I'm going.","right":"虽然下雨，但是我去。","wrong":"但是下雨，虽然我去。","full":["虽然|下雨|，|但是|我|去|。","suī rán|xià yǔ||dàn shì|wǒ|qù|","Although it's raining, I'm going."]}]},{"id":"haishi","level":2,"title":"还是 and 或者: or","pattern":"Question: A 还是 B？ · Statement: A 或者 B","why":"Chinese has two words for \"or\". 还是 asks which one. 或者 says either one will do.","mark":["还是","或者"],"mistake":["你喝茶或者咖啡？","你喝茶还是咖啡？","When you are asking which, use 还是."],"ex":[["你|喝茶|还是|咖啡|？","nǐ|hē chá|hái shi|kā fēi|","Are you having tea or coffee?"],["你|今天|去|还是|明天|去|？","nǐ|jīn tiān|qù|hái shi|míng tiān|qù|","Are you going today or tomorrow?"],["茶|或者|咖啡|都|可以|。","chá|huò zhě|kā fēi|dōu|kě yǐ|","Tea or coffee, either is fine."]],"gap":[{"en":"Are you having tea or coffee?","before":"你喝茶","after":"喝咖啡？","a":"还是","wrong":["或者","和","也"],"pins":{"还是":"hái shi","或者":"huò zhě","和":"hé","也":"yě"},"full":["你|喝茶|还是|喝|咖啡|？","nǐ|hē chá|hái shi|hē|kā fēi|","Are you having tea or coffee?"]},{"en":"Is he a teacher or a student?","before":"他是老师","after":"学生？","a":"还是","wrong":["或者","和","也"],"pins":{"还是":"hái shi","或者":"huò zhě","和":"hé","也":"yě"},"full":["他|是|老师|还是|学生|？","tā|shì|lǎo shī|hái shi|xué sheng|","Is he a teacher or a student?"]},{"en":"Today or tomorrow, either is fine.","before":"今天","after":"明天都可以。","a":"或者","wrong":["还是","也","吗"],"pins":{"或者":"huò zhě","还是":"hái shi","也":"yě","吗":"ma"},"full":["今天|或者|明天|都|可以|。","jīn tiān|huò zhě|míng tiān|dōu|kě yǐ|","Today or tomorrow, either is fine."]}],"order":[{"en":"Are you having tea or coffee?","a":"你|喝|茶|还是|咖啡|？","alt":["你|喝|咖啡|还是|茶|？"],"full":["你|喝|茶|还是|咖啡|？","nǐ|hē|chá|hái shi|kā fēi|","Are you having tea or coffee?"]},{"en":"Is he a teacher or a student?","a":"他|是|老师|还是|学生|？","alt":["他|是|学生|还是|老师|？"],"full":["他|是|老师|还是|学生|？","tā|shì|lǎo shī|hái shi|xué sheng|","Is he a teacher or a student?"]},{"en":"Are you going today or tomorrow?","a":"你|今天|去|还是|明天|去|？","alt":["你|明天|去|还是|今天|去|？"],"full":["你|今天|去|还是|明天|去|？","nǐ|jīn tiān|qù|hái shi|míng tiān|qù|","Are you going today or tomorrow?"]}],"spot":[{"en":"Are you having tea or coffee?","right":"你喝茶还是咖啡？","wrong":"你喝茶或者咖啡？","full":["你|喝茶|还是|咖啡|？","nǐ|hē chá|hái shi|kā fēi|","Are you having tea or coffee?"]},{"en":"Are you going or not?","right":"你去还是不去？","wrong":"你去或者不去？","full":["你|去|还是|不|去|？","nǐ|qù|hái shi|bù|qù|","Are you going or not?"]}]},{"id":"yijing","level":2,"title":"已经…了: already","pattern":"已经 + verb + 了","why":"已经 means \"already\", and the sentence normally ends in 了, to say that this is now how things stand.","mark":["已经","了"],"mistake":["我已经吃。","我已经吃了。","已经 needs its 了."],"ex":[["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."],["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."],["现在|已经|八|点|了|。","xiàn zài|yǐ jīng|bā|diǎn|le|","It is already eight o'clock."]],"gap":[{"en":"I have already eaten.","before":"我","after":"吃饭了。","a":"已经","wrong":["正在","很","也"],"pins":{"已经":"yǐ jīng","正在":"zhèng zài","很":"hěn","也":"yě"},"full":["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."]},{"en":"He has already gone home.","before":"他已经回家","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."]},{"en":"It is already nine o'clock.","before":"现在","after":"九点了。","a":"已经","wrong":["很","是","也"],"pins":{"已经":"yǐ jīng","很":"hěn","是":"shì","也":"yě"},"full":["现在|已经|九|点|了|。","xiàn zài|yǐ jīng|jiǔ|diǎn|le|","It is already nine o'clock."]}],"order":[{"en":"I have already eaten.","a":"我|已经|吃饭|了|。","alt":[],"full":["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."]},{"en":"He has already gone home.","a":"他|已经|回家|了|。","alt":[],"full":["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."]},{"en":"It is already ten o'clock.","a":"现在|已经|十|点|了|。","alt":[],"full":["现在|已经|十|点|了|。","xiàn zài|yǐ jīng|shí|diǎn|le|","It is already ten o'clock."]}],"spot":[{"en":"He has already come.","right":"他已经来了。","wrong":"他来已经了。","full":["他|已经|来|了|。","tā|yǐ jīng|lái|le|","He has already come."]},{"en":"I have already eaten.","right":"我已经吃了。","wrong":"我已经吃。","full":["我|已经|吃|了|。","wǒ|yǐ jīng|chī|le|","I have already eaten."]}]},{"id":"youdian","level":2,"title":"有点儿 and 一点儿: a bit","pattern":"有点儿 + adjective · adjective + 一点儿","why":"有点儿 goes before the adjective, and usually sounds like a complaint: a bit too cold. 一点儿 goes after it, and compares or asks for a change: a bit cheaper.","mark":["有点儿","一点儿"],"mistake":["我一点儿累。","我有点儿累。","Before an adjective, use 有点儿."],"ex":[["今天|有点儿|冷|。","jīn tiān|yǒu diǎn r|lěng|","It's a bit cold today."],["这|个|有点儿|贵|。","zhè|gè|yǒu diǎn r|guì|","This is a bit expensive."],["便宜|一点儿|吧|。","pián yi|yī diǎn r|ba|","Make it a bit cheaper."]],"gap":[{"en":"I'm a bit tired.","before":"我","after":"累。","a":"有点儿","wrong":["一点儿","是","的"],"pins":{"有点儿":"yǒu diǎn r","一点儿":"yī diǎn r","是":"shì","的":"de"},"full":["我|有点儿|累|。","wǒ|yǒu diǎn r|lèi|","I'm a bit tired."]},{"en":"It's a bit hot today.","before":"今天","after":"热。","a":"有点儿","wrong":["一点儿","是","的"],"pins":{"有点儿":"yǒu diǎn r","一点儿":"yī diǎn r","是":"shì","的":"de"},"full":["今天|有点儿|热|。","jīn tiān|yǒu diǎn r|rè|","It's a bit hot today."]},{"en":"Please be a bit quicker.","before":"请快","after":"。","a":"一点儿","wrong":["有点儿","的","吗"],"pins":{"一点儿":"yī diǎn r","有点儿":"yǒu diǎn r","的":"de","吗":"ma"},"full":["请|快|一点儿|。","qǐng|kuài|yī diǎn r|","Please be a bit quicker."]}],"order":[{"en":"It's a bit cold today.","a":"今天|有点儿|冷|。","alt":[],"full":["今天|有点儿|冷|。","jīn tiān|yǒu diǎn r|lěng|","It's a bit cold today."]},{"en":"This book is a bit expensive.","a":"这|本|书|有点儿|贵|。","alt":[],"full":["这|本|书|有点儿|贵|。","zhè|běn|shū|yǒu diǎn r|guì|","This book is a bit expensive."]},{"en":"I'm a bit tired today.","a":"我|今天|有点儿|累|。","alt":["今天|我|有点儿|累|。"],"full":["我|今天|有点儿|累|。","wǒ|jīn tiān|yǒu diǎn r|lèi|","I'm a bit tired today."]}],"spot":[{"en":"I'm a bit tired.","right":"我有点儿累。","wrong":"我一点儿累。","full":["我|有点儿|累|。","wǒ|yǒu diǎn r|lèi|","I'm a bit tired."]},{"en":"This is a bit expensive.","right":"这个有点儿贵。","wrong":"这个贵有点儿。","full":["这|个|有点儿|贵|。","zhè|gè|yǒu diǎn r|guì|","This is a bit expensive."]}]},{"id":"xian","level":2,"title":"先…然后: first, then","pattern":"先 + first thing，然后 + next thing","why":"先 goes before the first verb, after the subject. 然后 starts the second half of the sentence.","mark":["先","然后"],"mistake":["先我吃饭，然后看书。","我先吃饭，然后看书。","先 follows the subject."],"ex":[["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."],["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."],["我们|先|去|北京|，|然后|去|上海|。","wǒ men|xiān|qù|Běi jīng||rán hòu|qù|Shàng hǎi|","We'll go to Beijing first, then Shanghai."]],"gap":[{"en":"First I'll eat, then go to school.","before":"我","after":"吃饭，然后去学校。","a":"先","wrong":["也","很","都"],"pins":{"先":"xiān","也":"yě","很":"hěn","都":"dōu"},"full":["我|先|吃饭|，|然后|去|学校|。","wǒ|xiān|chī fàn||rán hòu|qù|xué xiào|","First I'll eat, then go to school."]},{"en":"First I'll work, then read.","before":"我先工作，","after":"看书。","a":"然后","wrong":["先","也","很"],"pins":{"然后":"rán hòu","先":"xiān","也":"yě","很":"hěn"},"full":["我|先|工作|，|然后|看书|。","wǒ|xiān|gōng zuò||rán hòu|kàn shū|","First I'll work, then read."]},{"en":"Have your tea first, then we'll leave.","before":"你","after":"喝茶，然后我们走。","a":"先","wrong":["也","很","的"],"pins":{"先":"xiān","也":"yě","很":"hěn","的":"de"},"full":["你|先|喝茶|，|然后|我们|走|。","nǐ|xiān|hē chá||rán hòu|wǒ men|zǒu|","Have your tea first, then we'll leave."]}],"order":[{"en":"First I'll eat, then I'll read.","a":"我|先|吃饭|，|然后|看书|。","alt":[],"full":["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."]},{"en":"We'll go to Beijing first, then Shanghai.","a":"我们|先|去|北京|，|然后|去|上海|。","alt":[],"full":["我们|先|去|北京|，|然后|去|上海|。","wǒ men|xiān|qù|Běi jīng||rán hòu|qù|Shàng hǎi|","We'll go to Beijing first, then Shanghai."]},{"en":"You go first, then I'll go.","a":"你|先|去|，|然后|我|去|。","alt":[],"full":["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."]}],"spot":[{"en":"First I'll eat, then I'll read.","right":"我先吃饭，然后看书。","wrong":"先我吃饭，然后看书。","full":["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."]},{"en":"You go first, then I'll go.","right":"你先去，然后我去。","wrong":"你然后去，先我去。","full":["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."]}]},{"id":"ba3","level":3,"title":"把: doing something to a thing","pattern":"Subject + 把 + thing + verb + result","why":"把 brings the thing to the front, to say what happens to it. The verb can't stand alone at the end: it needs a result, a place, or 了.","mark":["把"],"mistake":["我把书放。","我把书放在桌子上。","After 把, the verb must say what became of the thing."],"ex":[["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."],["他|把|茶|喝|了|。","tā|bǎ|chá|hē|le|","He drank the tea."],["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]],"gap":[{"en":"I put the book on the table.","before":"我","after":"书放在桌子上。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."]},{"en":"Please close the door.","before":"请","after":"门关上。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]},{"en":"He drank the water.","before":"他","after":"水喝了。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["他|把|水|喝|了|。","tā|bǎ|shuǐ|hē|le|","He drank the water."]}],"order":[{"en":"I put the book on the table.","a":"我|把|书|放|在|桌子|上|。","alt":[],"full":["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."]},{"en":"Please close the door.","a":"请|把|门|关上|。","alt":[],"full":["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]},{"en":"She drank the tea.","a":"她|把|茶|喝|了|。","alt":[],"full":["她|把|茶|喝|了|。","tā|bǎ|chá|hē|le|","She drank the tea."]}],"spot":[{"en":"I put the book on the table.","right":"我把书放在桌子上了。","wrong":"我把书放。","full":["我|把|书|放|在|桌子|上|了|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|le|","I put the book on the table."]},{"en":"He drank the water.","right":"他把水喝了。","wrong":"他喝把水了。","full":["他|把|水|喝|了|。","tā|bǎ|shuǐ|hē|le|","He drank the water."]}]},{"id":"bei","level":3,"title":"被: having something done to it","pattern":"Thing + 被 + doer + verb + result","why":"被 puts what the action happened to first, then who did it. It is the reverse of 把, and it often tells of something unwelcome.","mark":["被"],"mistake":["苹果被他吃。","苹果被他吃了。","被, like 把, needs a result: here, 了."],"ex":[["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."],["苹果|被|吃|了|。","píng guǒ|bèi|chī|le|","The apple got eaten."],["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]],"gap":[{"en":"My phone was taken by him.","before":"我的手机","after":"他拿走了。","a":"被","wrong":["把","是","很"],"pins":{"被":"bèi","把":"bǎ","是":"shì","很":"hěn"},"full":["我|的|手机|被|他|拿走|了|。","wǒ|de|shǒu jī|bèi|tā|ná zǒu|le|","My phone was taken by him."]},{"en":"The apple got eaten.","before":"苹果","after":"吃了。","a":"被","wrong":["把","是","很"],"pins":{"被":"bèi","把":"bǎ","是":"shì","很":"hěn"},"full":["苹果|被|吃|了|。","píng guǒ|bèi|chī|le|","The apple got eaten."]},{"en":"He was seen by the teacher.","before":"他被老师看见","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]}],"order":[{"en":"My book was taken by him.","a":"我|的|书|被|他|拿走|了|。","alt":[],"full":["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."]},{"en":"The apple was eaten by him.","a":"苹果|被|他|吃|了|。","alt":[],"full":["苹果|被|他|吃|了|。","píng guǒ|bèi|tā|chī|le|","The apple was eaten by him."]},{"en":"He was seen by the teacher.","a":"他|被|老师|看见|了|。","alt":[],"full":["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]}],"spot":[{"en":"The apple was eaten by him.","right":"苹果被他吃了。","wrong":"苹果被他吃。","full":["苹果|被|他|吃|了|。","píng guǒ|bèi|tā|chī|le|","The apple was eaten by him."]},{"en":"My book was taken by him.","right":"我的书被他拿走了。","wrong":"他被我的书拿走了。","full":["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."]}]},{"id":"zhe","level":3,"title":"着: staying that way","pattern":"Verb + 着","why":"着 after a verb says the state carries on: the door stays open. Followed by another verb, it says how the second action is done: sitting and reading.","mark":["着"],"mistake":["门开着了。","门开着。","着 says it is still that way, so it doesn't take 了."],"ex":[["门|开|着|。","mén|kāi|zhe|","The door is open."],["他|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","He is wearing red clothes."],["她|坐|着|看书|。","tā|zuò|zhe|kàn shū|","She sits and reads."]],"gap":[{"en":"The door is open.","before":"门开","after":"。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"He is wearing red clothes.","before":"他穿","after":"红色的衣服。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["他|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","He is wearing red clothes."]},{"en":"She sits and reads.","before":"她坐","after":"看书。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["她|坐|着|看书|。","tā|zuò|zhe|kàn shū|","She sits and reads."]}],"order":[{"en":"The door is open.","a":"门|开|着|。","alt":[],"full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"I sit and drink tea.","a":"我|坐|着|喝|茶|。","alt":[],"full":["我|坐|着|喝|茶|。","wǒ|zuò|zhe|hē|chá|","I sit and drink tea."]},{"en":"She is wearing red clothes.","a":"她|穿|着|红色|的|衣服|。","alt":[],"full":["她|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","She is wearing red clothes."]}],"spot":[{"en":"The door is open.","right":"门开着。","wrong":"门开着了。","full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"He sits and reads.","right":"他坐着看书。","wrong":"他看书坐着。","full":["他|坐|着|看书|。","tā|zuò|zhe|kàn shū|","He sits and reads."]}]},{"id":"di","level":3,"title":"地: how, before a verb","pattern":"Adjective + 地 + verb","why":"地 turns a description into an adverb: 慢慢地 is \"slowly\". All three de sound alike: 的 goes before a noun, 地 before a verb, and 得 after a verb.","mark":["地"],"mistake":["她走慢慢地。","她慢慢地走。","地 and its description come before the verb."],"ex":[["他|高兴|地|说|。","tā|gāo xìng|de|shuō|","He said happily."],["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."],["我们|认真|地|学习|。","wǒ men|rèn zhēn|de|xué xí|","We study seriously."]],"gap":[{"en":"He laughed happily.","before":"他高兴","after":"笑了。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["他|高兴|地|笑|了|。","tā|gāo xìng|de|xiào|le|","He laughed happily."]},{"en":"She walks slowly.","before":"她慢慢","after":"走。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"You should study seriously.","before":"你要认真","after":"学习。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["你|要|认真|地|学习|。","nǐ|yào|rèn zhēn|de|xué xí|","You should study seriously."]}],"order":[{"en":"He said happily.","a":"他|高兴|地|说|。","alt":[],"full":["他|高兴|地|说|。","tā|gāo xìng|de|shuō|","He said happily."]},{"en":"She walks slowly.","a":"她|慢慢|地|走|。","alt":[],"full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"We study Chinese seriously.","a":"我们|认真|地|学习|中文|。","alt":[],"full":["我们|认真|地|学习|中文|。","wǒ men|rèn zhēn|de|xué xí|Zhōng wén|","We study Chinese seriously."]}],"spot":[{"en":"She walks slowly.","right":"她慢慢地走。","wrong":"她走慢慢地。","full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"He laughed happily.","right":"他高兴地笑了。","wrong":"他笑高兴地了。","full":["他|高兴|地|笑|了|。","tā|gāo xìng|de|xiào|le|","He laughed happily."]}]},{"id":"ruguo","level":3,"title":"如果…就: if, then","pattern":"如果 + condition，subject + 就 + result","why":"如果 sets the condition. 就 goes in the second half, after the subject and right before the verb.","mark":["如果","就"],"mistake":["如果你去，就我去。","如果你去，我就去。","就 follows the subject."],"ex":[["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."],["如果|你|想|去|，|我们|就|去|。","rú guǒ|nǐ|xiǎng|qù||wǒ men|jiù|qù|","If you want to go, we'll go."],["如果|有|时间|，|我|就|看书|。","rú guǒ|yǒu|shí jiān||wǒ|jiù|kàn shū|","If I have time, I'll read."]],"gap":[{"en":"If it rains tomorrow, I won't go.","before":"","after":"明天下雨，我就不去。","a":"如果","wrong":["因为","虽然","所以"],"pins":{"如果":"rú guǒ","因为":"yīn wèi","虽然":"suī rán","所以":"suǒ yǐ"},"full":["如果|明天|下雨|，|我|就|不|去|。","rú guǒ|míng tiān|xià yǔ||wǒ|jiù|bù|qù|","If it rains tomorrow, I won't go."]},{"en":"If you come, I'll be happy.","before":"如果你来，我","after":"很高兴。","a":"就","wrong":["所以","的","吗"],"pins":{"就":"jiù","所以":"suǒ yǐ","的":"de","吗":"ma"},"full":["如果|你|来|，|我|就|很|高兴|。","rú guǒ|nǐ|lái||wǒ|jiù|hěn|gāo xìng|","If you come, I'll be happy."]},{"en":"If we have time, we'll go to Beijing.","before":"如果有时间，我们","after":"去北京。","a":"就","wrong":["的","吗","很"],"pins":{"就":"jiù","的":"de","吗":"ma","很":"hěn"},"full":["如果|有|时间|，|我们|就|去|北京|。","rú guǒ|yǒu|shí jiān||wǒ men|jiù|qù|Běi jīng|","If we have time, we'll go to Beijing."]}],"order":[{"en":"If it rains, I won't go.","a":"如果|下雨|，|我|就|不|去|。","alt":[],"full":["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."]},{"en":"If I have time, I'll read.","a":"如果|有|时间|，|我|就|看书|。","alt":[],"full":["如果|有|时间|，|我|就|看书|。","rú guǒ|yǒu|shí jiān||wǒ|jiù|kàn shū|","If I have time, I'll read."]},{"en":"If you want to go, we'll go.","a":"如果|你|想|去|，|我们|就|去|。","alt":[],"full":["如果|你|想|去|，|我们|就|去|。","rú guǒ|nǐ|xiǎng|qù||wǒ men|jiù|qù|","If you want to go, we'll go."]}],"spot":[{"en":"If it rains, I won't go.","right":"如果下雨，我就不去。","wrong":"下雨如果，就我不去。","full":["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."]},{"en":"If you go, I'll go.","right":"如果你去，我就去。","wrong":"如果你去，就我去。","full":["如果|你|去|，|我|就|去|。","rú guǒ|nǐ|qù||wǒ|jiù|qù|","If you go, I'll go."]}]},{"id":"yi-jiu","level":3,"title":"一…就: as soon as","pattern":"Subject + 一 + verb，就 + verb","why":"一 before the first verb and 就 before the second say that the second thing follows straight away.","mark":["一","就"],"mistake":["一我回家就吃饭。","我一回家就吃饭。","一 follows the subject."],"ex":[["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."],["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."],["她|一|到|就|给|我|打电话|。","tā|yī|dào|jiù|gěi|wǒ|dǎ diàn huà|","She phoned me as soon as she arrived."]],"gap":[{"en":"As soon as I get home, I eat.","before":"我","after":"回家就吃饭。","a":"一","wrong":["也","很","的"],"pins":{"一":"yī","也":"yě","很":"hěn","的":"de"},"full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"He understands as soon as he looks.","before":"他一看","after":"懂。","a":"就","wrong":["也","很","的"],"pins":{"就":"jiù","也":"yě","很":"hěn","的":"de"},"full":["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."]},{"en":"She phoned me as soon as she arrived.","before":"她一到","after":"给我打电话。","a":"就","wrong":["也","很","的"],"pins":{"就":"jiù","也":"yě","很":"hěn","的":"de"},"full":["她|一|到|就|给|我|打电话|。","tā|yī|dào|jiù|gěi|wǒ|dǎ diàn huà|","She phoned me as soon as she arrived."]}],"order":[{"en":"As soon as I get home, I eat.","a":"我|一|回家|就|吃饭|。","alt":[],"full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"As soon as he arrives, he makes a phone call.","a":"他|一|到|就|打|电话|。","alt":[],"full":["他|一|到|就|打|电话|。","tā|yī|dào|jiù|dǎ|diàn huà|","As soon as he arrives, he makes a phone call."]},{"en":"She understands as soon as she looks.","a":"她|一|看|就|懂|。","alt":[],"full":["她|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","She understands as soon as she looks."]}],"spot":[{"en":"As soon as I get home, I eat.","right":"我一回家就吃饭。","wrong":"一我回家就吃饭。","full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"He understands as soon as he looks.","right":"他一看就懂。","wrong":"他看一懂就。","full":["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."]}]},{"id":"yuelaiyue","level":3,"title":"越来越: more and more","pattern":"越来越 + adjective","why":"越来越 says something keeps changing, getting more and more so. It already means \"more\", so 很 can't go with it.","mark":["越来越"],"mistake":["天气越来越很冷。","天气越来越冷。","No 很 after 越来越."],"ex":[["天气|越来越|冷|。","tiān qì|yuè lái yuè|lěng|","The weather is getting colder and colder."],["我|的|中文|越来越|好|。","wǒ|de|Zhōng wén|yuè lái yuè|hǎo|","My Chinese is getting better and better."],["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more and more expensive."]],"gap":[{"en":"The weather is getting colder.","before":"天气","after":"冷了。","a":"越来越","wrong":["很","是","的"],"pins":{"越来越":"yuè lái yuè","很":"hěn","是":"shì","的":"de"},"full":["天气|越来越|冷|了|。","tiān qì|yuè lái yuè|lěng|le|","The weather is getting colder."]},{"en":"Your Chinese is getting better.","before":"你的中文","after":"好了。","a":"越来越","wrong":["是","的","吗"],"pins":{"越来越":"yuè lái yuè","是":"shì","的":"de","吗":"ma"},"full":["你|的|中文|越来越|好|了|。","nǐ|de|Zhōng wén|yuè lái yuè|hǎo|le|","Your Chinese is getting better."]},{"en":"Things are getting more expensive.","before":"东西越来越","after":"。","a":"贵","wrong":["很","是","吗"],"pins":{"贵":"guì","很":"hěn","是":"shì","吗":"ma"},"full":["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more expensive."]}],"order":[{"en":"The weather is getting hotter.","a":"天气|越来越|热|了|。","alt":[],"full":["天气|越来越|热|了|。","tiān qì|yuè lái yuè|rè|le|","The weather is getting hotter."]},{"en":"My Chinese is getting better.","a":"我|的|中文|越来越|好|。","alt":[],"full":["我|的|中文|越来越|好|。","wǒ|de|Zhōng wén|yuè lái yuè|hǎo|","My Chinese is getting better."]},{"en":"Things here are getting more expensive.","a":"这儿|的|东西|越来越|贵|。","alt":[],"full":["这儿|的|东西|越来越|贵|。","zhèr|de|dōng xi|yuè lái yuè|guì|","Things here are getting more expensive."]}],"spot":[{"en":"The weather is getting colder.","right":"天气越来越冷。","wrong":"天气越来越很冷。","full":["天气|越来越|冷|。","tiān qì|yuè lái yuè|lěng|","The weather is getting colder."]},{"en":"Things are getting more expensive.","right":"东西越来越贵。","wrong":"东西贵越来越。","full":["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more expensive."]}]},{"id":"you-you","level":3,"title":"又…又: both at once","pattern":"又 + A + 又 + B","why":"又…又 says two things are true at the same time, each with its own 又. They are usually both good, or both bad.","mark":["又"],"mistake":["她又高，漂亮。","她又高又漂亮。","Each one takes a 又."],"ex":[["这|个|又|便宜|又|好|。","zhè|gè|yòu|pián yi|yòu|hǎo|","This is both cheap and good."],["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."],["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]],"gap":[{"en":"This apple is big and tasty.","before":"这个苹果又大","after":"好吃。","a":"又","wrong":["和","也","很"],"pins":{"又":"yòu","和":"hé","也":"yě","很":"hěn"},"full":["这|个|苹果|又|大|又|好吃|。","zhè|gè|píng guǒ|yòu|dà|yòu|hǎo chī|","This apple is big and tasty."]},{"en":"He is busy and tired.","before":"他","after":"忙又累。","a":"又","wrong":["和","很","的"],"pins":{"又":"yòu","和":"hé","很":"hěn","的":"de"},"full":["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]},{"en":"She is tall and beautiful.","before":"她又高又","after":"。","a":"漂亮","wrong":["很","是","吗"],"pins":{"漂亮":"piào liang","很":"hěn","是":"shì","吗":"ma"},"full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]}],"order":[{"en":"She is tall and beautiful.","a":"她|又|高|又|漂亮|。","alt":["她|又|漂亮|又|高|。"],"full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]},{"en":"This is both cheap and good.","a":"这个|又|便宜|又|好|。","alt":["这个|又|好|又|便宜|。"],"full":["这个|又|便宜|又|好|。","zhè gè|yòu|pián yi|yòu|hǎo|","This is both cheap and good."]},{"en":"I am tired and hungry.","a":"我|又|累|又|饿|。","alt":["我|又|饿|又|累|。"],"full":["我|又|累|又|饿|。","wǒ|yòu|lèi|yòu|è|","I am tired and hungry."]}],"spot":[{"en":"She is tall and beautiful.","right":"她又高又漂亮。","wrong":"她又高，漂亮。","full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]},{"en":"He is busy and tired.","right":"他又忙又累。","wrong":"他忙又又累。","full":["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]}]},{"id":"chule","level":3,"title":"除了: besides, or except","pattern":"除了 + A，subject + 也 or 都 + verb","why":"The second half decides the meaning. With 也, A is included: \"besides A, also\". With 都, A is left out: \"everyone except A\".","mark":["除了"],"mistake":["除了茶，我喜欢也咖啡。","除了茶，我也喜欢咖啡。","也 comes before the verb."],"ex":[["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."],["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."],["除了|星期天|，|我|每|天|都|工作|。","chú le|xīng qī tiān||wǒ|měi|tiān|dōu|gōng zuò|","I work every day except Sunday."]],"gap":[{"en":"Besides tea, I also like coffee.","before":"","after":"茶，我也喜欢咖啡。","a":"除了","wrong":["因为","虽然","如果"],"pins":{"除了":"chú le","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","before":"除了他，我们","after":"去。","a":"都","wrong":["很","的","吗"],"pins":{"都":"dōu","很":"hěn","的":"de","吗":"ma"},"full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]},{"en":"Besides Chinese, I can also speak English.","before":"除了中文，我","after":"会说英语。","a":"也","wrong":["很","的","吗"],"pins":{"也":"yě","很":"hěn","的":"de","吗":"ma"},"full":["除了|中文|，|我|也|会|说|英语|。","chú le|Zhōng wén||wǒ|yě|huì|shuō|Yīng yǔ|","Besides Chinese, I can also speak English."]}],"order":[{"en":"Besides tea, I also like coffee.","a":"除了|茶|，|我|也|喜欢|咖啡|。","alt":[],"full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","a":"除了|他|，|我们|都|去|。","alt":[],"full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]},{"en":"Besides Chinese, I can also speak English.","a":"除了|中文|，|我|也|会|说|英语|。","alt":[],"full":["除了|中文|，|我|也|会|说|英语|。","chú le|Zhōng wén||wǒ|yě|huì|shuō|Yīng yǔ|","Besides Chinese, I can also speak English."]}],"spot":[{"en":"Besides tea, I also like coffee.","right":"除了茶，我也喜欢咖啡。","wrong":"除了茶，我喜欢也咖啡。","full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","right":"除了他，我们都去。","wrong":"除了他，都我们去。","full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]}]}];
